struct AppState {
    lesson_num: u32,
    lesson: Vec<String>,  // list of ngrams in current lesson
    // Current position in lesson:
    // current_ngram_idx: which ngram we're typing
    // current_char_idx: which char within the ngram
    current_ngram_idx: usize,
    current_char_idx: usize,
    // For display: what's been typed so far (including spaces)
    typed_display: String,
    // Error tracking per ngram (whether there was an error in the current ngram)
    ngram_had_error: bool,
    // Which ngrams had errors (for display coloring)
    ngram_errors: Vec<bool>,  // true = had error
    ngram_completed: Vec<bool>,
    // Timing
    lesson_start: Option<Instant>,
    // Stats
    lessons_passed: u32,
    lessons_failed: u32,
    // WPM tracking
    avg_wpm: u32,
    last_wpm: u32,
    avg_acc: u32,
    last_acc: u32,
    // Lesson complete
    lesson_complete: bool,
    lesson_passed: bool,
    // Error count for current lesson
    total_errors: u32,
    total_correct: u32,
    // Space needed flag (after ngram complete, need space before next)
    needs_space: bool,
}

impl AppState {
    fn new(lesson: Vec<String>) -> Self {
        let n = lesson.len();
        AppState {
            lesson_num: 1,
            lesson,
            current_ngram_idx: 0,
            current_char_idx: 0,
            typed_display: String::new(),
            ngram_had_error: false,
            ngram_errors: vec![false; n],
            ngram_completed: vec![false; n],
            lesson_start: None,
            lessons_passed: 0,
            lessons_failed: 0,
            avg_wpm: 0,
            last_wpm: 0,
            avg_acc: 0,
            last_acc: 0,
            lesson_complete: false,
            lesson_passed: false,
            total_errors: 0,
            total_correct: 0,
            needs_space: false,
        }
    }

    fn next_lesson(&mut self, lesson: Vec<String>) {
        let n = lesson.len();
        self.lesson = lesson;
        self.current_ngram_idx = 0;
        self.current_char_idx = 0;
        self.typed_display = String::new();
        self.ngram_had_error = false;
        self.ngram_errors = vec![false; n];
        self.ngram_completed = vec![false; n];
        self.lesson_start = None;
        self.lesson_complete = false;
        self.lesson_passed = false;
        self.total_errors = 0;
        self.total_correct = 0;
        self.needs_space = false;
    }

    fn handle_char(&mut self, c: char) {
        if self.lesson_complete {
            return;
        }

        if self.needs_space {
            // Expecting a space to advance to next ngram
            if c == ' ' {
                self.typed_display.push(' ');
                self.needs_space = false;
                // Already advanced ngram_idx in handle_ngram_complete
            }
            // Wrong key while expecting space: ignore
            return;
        }

        if self.current_ngram_idx >= self.lesson.len() {
            return;
        }

        // Start timer on first character
        if self.lesson_start.is_none() && self.current_char_idx == 0 && self.current_ngram_idx == 0 {
            self.lesson_start = Some(Instant::now());
        }

        let current_ngram = &self.lesson[self.current_ngram_idx];
        let expected = current_ngram.chars().nth(self.current_char_idx);

        if let Some(exp) = expected {
            if c == exp {
                // Correct
                self.total_correct += 1;
                self.typed_display.push(c);
                self.current_char_idx += 1;

                if self.current_char_idx >= current_ngram.len() {
                    // Ngram complete
                    self.ngram_completed[self.current_ngram_idx] = true;
                    self.ngram_errors[self.current_ngram_idx] = self.ngram_had_error;
                    self.ngram_had_error = false;
                    self.current_ngram_idx += 1;
                    self.current_char_idx = 0;

                    if self.current_ngram_idx >= self.lesson.len() {
                        // Lesson complete
                        self.complete_lesson();
                    } else {
                        // Need space before next ngram
                        self.needs_space = true;
                    }
                }
            } else {
                // Wrong character
                self.total_errors += 1;
                self.ngram_had_error = true;
                self.typed_display.push(c);  // show wrong char
            }
        }
    }

    fn complete_lesson(&mut self) {
        self.lesson_complete = true;

        // Calculate WPM
        if let Some(start) = self.lesson_start {
            let elapsed = start.elapsed();
            let seconds = elapsed.as_secs_f64();
            if seconds > 0.0 {
                // Count non-space chars typed
                let chars_typed: u32 = self.lesson.iter().map(|s| s.len() as u32).sum();
                let words = chars_typed as f64 / 5.0;
                let wpm = (words / (seconds / 60.0)) as u32;
                self.last_wpm = wpm;

                // Update avg WPM
                let total_lessons = self.lessons_passed + self.lessons_failed + 1;
                if total_lessons == 1 {
                    self.avg_wpm = wpm;
                } else {
                    self.avg_wpm = ((self.avg_wpm as u64 * (total_lessons - 1) as u64 
                                    + wpm as u64) / total_lessons as u64) as u32;
                }
            }
        }

        // Calculate accuracy
        let total_keystrokes = self.total_correct + self.total_errors;
        let acc = if total_keystrokes > 0 {
            (self.total_correct as f64 / (self.total_correct + self.total_errors) as f64 * 100.0) as u32
        } else {
            100
        };
        self.last_acc = acc;

        let total_lessons = self.lessons_passed + self.lessons_failed + 1;
        if total_lessons == 1 {
            self.avg_acc = acc;
        } else {
            self.avg_acc = ((self.avg_acc as u64 * (total_lessons - 1) as u64 
                             + acc as u64) / total_lessons as u64) as u32;
        }
    }
}

fn build_lesson_spans<'a>(state: &AppState) -> Vec<Span<'a>> {
    let mut spans = Vec::new();

    for (i, ngram) in state.lesson.iter().enumerate() {
        if i > 0 {
            // Space separator
            if state.ngram_completed[i-1] {
                // Completed ngram: show bullet in cyan/yellow
                spans.push(Span::styled(
                    "•",
                    Style::default().fg(Color::Indexed(1)).add_modifier(Modifier::BOLD),
                ));
            } else {
                spans.push(Span::raw(" "));
            }
        }

        if state.ngram_completed[i] {
            // Completed ngram - show in green (no error) or red (with error)
            let color = if state.ngram_errors[i] {
                Color::Indexed(1)  // red for errors
            } else {
                Color::Indexed(2)  // green for clean
            };
            spans.push(Span::styled(
                ngram.clone(),
                Style::default().fg(color).add_modifier(Modifier::BOLD),
            ));
        } else if i == state.current_ngram_idx {
            // Currently being typed
            // Show typed chars in green/red, remaining in default
            let ngram_chars: Vec<char> = ngram.chars().collect();

            // Already typed chars in this ngram
            if state.current_char_idx > 0 {
                // The chars typed so far are in typed_display
                // Just show the whole ngram for simplicity
                // Actually we need to show typed chars differently
                // For now, show the whole ngram
            }

            // Show the ngram text  
            spans.push(Span::styled(
                ngram.clone(),
                Style::default().add_modifier(Modifier::BOLD),
            ));
        } else {
            // Future ngram
            spans.push(Span::raw(ngram.clone()));
        }
    }

    // Trailing bullet if lesson complete
    if state.lesson_complete {
        if let Some(last) = state.lesson.last() {
            let _ = last; // already handled above
        }
        spans.push(Span::styled(
            "•",
            Style::default().fg(Color::Indexed(1)).add_modifier(Modifier::BOLD),
        ));
    }

    spans
}

fn render_keyboard_staggered(
    f: &mut Frame,
    area: Rect,
    layout_keys: [[&str; 12]; 3],
    next_char: Option<char>,
) {
    // 12 keys * 4 chars each = 48 chars + 1 for last
    // Row 1: ┌───┬───┬...┬───┐
    // Row 2: │ q │ w │...│ ] │
    // etc.

    let style_normal = Style::default().fg(Color::Indexed(7));
    let style_highlight = Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD);

    // Find which key to highlight
    let highlight_row_col: Option<(usize, usize)> = if let Some(nc) = next_char {
        let rows: [[&str; 12]; 3] = layout_keys;
        let mut found = None;
        'outer: for (ri, row) in rows.iter().enumerate() {
            for (ci, key) in row.iter().enumerate() {
                if key.len() == 1 {
                    if key.chars().next() == Some(nc) {
                        found = Some((ri, ci));
                        break 'outer;
                    }
                }
            }
        }
        found
    } else {
        None
    };

    // Actually for the keyboard rendering, let me use a simple text approach
    // The keyboard has a specific visual layout that I need to replicate

    // Let me render using a Paragraph with pre-built text
    let row0 = &layout_keys[0];
    let row1 = &layout_keys[1];
    let row2 = &layout_keys[2];

    // Count keys per row (non-empty keys)
    let row0_keys: Vec<&str> = row0.iter().filter(|&&k| k != " ").copied().collect();
    let row1_keys: Vec<&str> = row1.iter().filter(|&&k| k != " ").copied().collect();
    let row2_keys: Vec<&str> = row2.iter().filter(|&&k| k != " ").copied().collect();

    // Build keyboard lines with boxes
    // Row 0: ┌───┬───┬...┬───┐
    // Row 0 content: │ q │ w │...│ ] │
    // Row 0 bottom / Row 1 top: └┬──┴┬──┴...┬──┘ (with offsets for stagger)
    // Row 1 content: │ a │ s │...│ ' │
    // Row 1 bottom / Row 2 top: └┬──┴┬──┴...┬──┘
    // Row 2 content: │ z │ x │...│ / │
    // Row 2 bottom: └───┴───┴...┴───┘

    // For staggered layout, rows 1 and 2 are offset by 1 and 2 chars respectively
    let offset = 14; // padding from left

    let build_top_row = |n: usize| -> String {
        let mut s = String::new();
        s.push('┌');
        for i in 0..n {
            s.push_str("───");
            if i < n - 1 { s.push('┬'); }
        }
        s.push('┐');
        s
    };

    let build_content_row = |keys: &[&str], highlight: Option<usize>| -> Vec<Span<'static>> {
        let mut spans = Vec::new();
        spans.push(Span::styled("│", Style::default().fg(Color::Indexed(7))));
        for (i, key) in keys.iter().enumerate() {
            let content = format!(" {} ", key);
            if let Some(hi) = highlight {
                if i == hi {
                    spans.push(Span::styled(content, Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD)));
                } else {
                    spans.push(Span::styled(content, Style::default().fg(Color::Indexed(7))));
                }
            } else {
                spans.push(Span::styled(content, Style::default().fg(Color::Indexed(7))));
            }
            spans.push(Span::styled("│", Style::default().fg(Color::Indexed(7))));
        }
        spans
    };

    let build_bottom_to_next_row = |n_top: usize, n_bot: usize| -> String {
        // └┬──┴┬──┴...
        let mut s = String::new();
        s.push('└');
        // This is complex stagger logic, simplified here
        for i in 0..n_top.max(n_bot) {
            if i < n_top - 1 {
                s.push_str("┬──┴");
            }
        }
        s.push('┘');
        s
    };

    // For simplicity, use pre-built keyboard string 
    // Standard QWERTY keyboard layout drawing:
    let (r0h, r1h, r2h) = match highlight_row_col {
        Some((0, c)) => (Some(c), None, None),
        Some((1, c)) => (None, Some(c), None),
        Some((2, c)) => (None, None, Some(c)),
        _ => (None, None, None),
    };

    // Build the keyboard lines
    let n0 = row0_keys.len();
    let n1 = row1_keys.len();
    let n2 = row2_keys.len();

    let indent0 = " ".repeat(offset);
    let indent1 = " ".repeat(offset + 1);
    let indent2 = " ".repeat(offset + 2);

    // Row 0 top border
    let mut top_line = format!("{}┌", indent0);
    for i in 0..n0 {
        top_line.push_str("───");
        if i < n0 - 1 { top_line.push('┬'); }
    }
    top_line.push('┐');

    // Row 0 content
    // Row 0 middle/bottom (staggered join with row 1)
    let mut mid01_line = format!("{}└", indent0);
    for i in 0..n0 {
        mid01_line.push('┬');
        mid01_line.push_str("──");
        if i < n0 - 1 { mid01_line.push('┴'); }
    }
    mid01_line.push('┘');

    // Row 1 middle/bottom
    let mut mid12_line = format!("{}└", indent1);
    for i in 0..n1 {
        mid12_line.push('┬');
        mid12_line.push_str("──");
        if i < n1 - 1 { mid12_line.push('┴'); }
    }
    mid12_line.push('┘');

    // Row 2 bottom
    let mut bot_line = format!("{}└", indent2);
    for i in 0..n2 {
        bot_line.push_str("───");
        if i < n2 - 1 { bot_line.push('┴'); }
    }
    bot_line.push('┘');

    // Now render each line
    let lines_count = 7;
    let y_start = area.y + (area.height.saturating_sub(lines_count)) / 2;

    if y_start + lines_count > area.y + area.height {
        return;
    }

    // We'll render as a Paragraph instead
    let mut kb_lines = Vec::new();

    kb_lines.push(Line::from(vec![Span::styled(top_line, Style::default().fg(Color::Indexed(7)))]));

