}

fn render_keyboard_ortho(
    f: &mut Frame,
    area: Rect,
    layout_keys: [[&str; 12]; 3],
    next_char: Option<char>,
) {
    let offset = 13; // padding from left
    let indent = " ".repeat(offset);

    let (r0h, r1h, r2h) = if let Some(nc) = next_char {
        let mut found = (None, None, None);
        'outer: for (ri, row) in layout_keys.iter().enumerate() {
            for (ci, key) in row.iter().enumerate() {
                if key.len() == 1 && key.chars().next() == Some(nc) {
                    match ri {
                        0 => found.0 = Some(ci),
                        1 => found.1 = Some(ci),
                        2 => found.2 = Some(ci),
                        _ => {}
                    }
                    break 'outer;
                }
            }
        }
        found
    } else {
        (None, None, None)
    };

    let n = 12; // fixed 12 columns for ortho

    let build_top = || -> String {
        let mut s = format!("{indent}┌");
        for i in 0..n {
            s.push_str("───");
            if i < n - 1 { s.push('┬'); }
        }
        s.push('┐');
        s
    };

    let build_mid = || -> String {
        let mut s = format!("{indent}├");
        for i in 0..n {
            s.push_str("───");
            if i < n - 1 { s.push('┼'); }
        }
        s.push('┤');
        s
    };

    let build_bot = || -> String {
        let mut s = format!("{indent}└");
        for i in 0..n {
            s.push_str("───");
            if i < n - 1 { s.push('┴'); }
        }
        s.push('┘');
        s
    };

    let mut kb_lines = Vec::new();

    kb_lines.push(Line::from(Span::styled(build_top(), Style::default().fg(Color::Indexed(7)))));

    // Row 0
    let mut row0_line = vec![Span::styled(format!("{indent}│"), Style::default().fg(Color::Indexed(7)))];
    for i in 0..n {
        let key = layout_keys[0][i];
        let content = format!(" {} ", if key == " " { "△" } else { key });
        let style = if r0h == Some(i) && key != " " {
            Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD)
        } else if key == " " {
            Style::default().fg(Color::Indexed(8))
        } else {
            Style::default().fg(Color::Indexed(7))
        };
        row0_line.push(Span::styled(content, style));
        row0_line.push(Span::styled("│", Style::default().fg(Color::Indexed(7))));
    }
    kb_lines.push(Line::from(row0_line));

    kb_lines.push(Line::from(Span::styled(build_mid(), Style::default().fg(Color::Indexed(7)))));

    // Row 1
    let mut row1_line = vec![Span::styled(format!("{indent}│"), Style::default().fg(Color::Indexed(7)))];
    for i in 0..n {
        let key = layout_keys[1][i];
        let content = format!(" {} ", if key == " " { "△" } else { key });
        let style = if r1h == Some(i) && key != " " {
            Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD)
        } else if key == " " {
            Style::default().fg(Color::Indexed(8))
        } else {
            Style::default().fg(Color::Indexed(7))
        };
        row1_line.push(Span::styled(content, style));
        row1_line.push(Span::styled("│", Style::default().fg(Color::Indexed(7))));
    }
    kb_lines.push(Line::from(row1_line));

    kb_lines.push(Line::from(Span::styled(build_mid(), Style::default().fg(Color::Indexed(7)))));

    // Row 2
    let mut row2_line = vec![Span::styled(format!("{indent}│"), Style::default().fg(Color::Indexed(7)))];
    for i in 0..n {
        let key = layout_keys[2][i];
        let content = format!(" {} ", if key == " " { "△" } else { key });
        let style = if r2h == Some(i) && key != " " {
            Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD)
        } else if key == " " {
            Style::default().fg(Color::Indexed(8))
        } else {
            Style::default().fg(Color::Indexed(7))
        };
        row2_line.push(Span::styled(content, style));
        row2_line.push(Span::styled("│", Style::default().fg(Color::Indexed(7))));
    }
    kb_lines.push(Line::from(row2_line));

    kb_lines.push(Line::from(Span::styled(build_bot(), Style::default().fg(Color::Indexed(7)))));

    let para = Paragraph::new(kb_lines);
    f.render_widget(para, area);
}

fn render_ui(f: &mut Frame, state: &AppState, args: &Args) {
    let size = f.area();

    // Minimum size check
    let min_width = 80;
    let min_height = 13;
    if size.width < min_width || size.height < min_height {
        let msg = format!(
            "Please resize your terminal to at least {}x{}.",
            min_width, min_height
        );
        let p = Paragraph::new(vec![
            Line::from(""),
            Line::from(Span::raw(msg)),
            Line::from(""),
            Line::from("             <esc> or <ctrl-c> to quit"),
        ]);
        f.render_widget(p, size);
        return;
    }

    // Outer block
    let outer_block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default())
        .title(Span::styled(
            " Quit <esc> ",
            Style::default().fg(Color::Indexed(4)).add_modifier(Modifier::BOLD),
        ))
        .title_alignment(Alignment::Right);

    let inner = outer_block.inner(size);
    f.render_widget(outer_block, size);

    // Title line
    let title_line = Line::from(vec![
        Span::styled("ngrrram!", Style::default().add_modifier(Modifier::BOLD)),
        Span::styled("   by winterveil", Style::default().fg(Color::Indexed(7)).add_modifier(Modifier::ITALIC)),
    ]);

    // Separator
    let sep = "─".repeat(inner.width as usize);

    // Header: Lesson number and stats
    let lesson_header = Line::from(vec![
        Span::raw(format!("    Lesson #{}", state.lesson_num)),
        Span::raw(" ".repeat(inner.width as usize - 
            format!("    Lesson #{}", state.lesson_num).len() - 
            format!("✔: {}, ✘: {}", state.lessons_passed, state.lessons_failed).len() - 4)),
        Span::styled(format!("✔: {}", state.lessons_passed), Style::default().fg(Color::Indexed(2))),
        Span::raw(", "),
        Span::styled(format!("✘: {}", state.lessons_failed), Style::default().fg(Color::Indexed(1))),
        Span::raw("    "),
    ]);

    // Determine keyboard layout to show
    let kb_layout_name = if !args.emu_out.is_empty() {
        args.emu_out.as_str()
    } else {
        "qwerty"
    };
    let kb_layout = get_keyboard_layout(kb_layout_name);

    // Keyboard height
    let kb_height = if args.nokb { 0 } else { 7u16 };

    // Build layout constraints
    let needs_cat = args.cat;

    // Calculate areas
    // Title: 1 line
    // Sep: 1 line  
    // Header: 1 line
    // Sep: 1 line
    // Blank: 1 line
    // Lesson text: 1 line
    // Typed: 1 line
    // Blank: 1 line
    // KB: 7 lines (if shown)
    // Sep: 1 line
    // Stats: 2 lines

    let mut y = inner.y;

    // Title
    let title_area = Rect::new(inner.x, y, inner.width, 1);
    let title_para = Paragraph::new(title_line).alignment(Alignment::Center);
    f.render_widget(title_para, title_area);
    y += 1;

    // Separator
    let sep_area = Rect::new(inner.x, y, inner.width, 1);
    f.render_widget(Paragraph::new(sep.clone()), sep_area);
    y += 1;

    // Header line
    let header_area = Rect::new(inner.x, y, inner.width, 1);

    let right_part = format!("✔: {}, ✘: {}", state.lessons_passed, state.lessons_failed);
    let left_part = format!("    Lesson #{}", state.lesson_num);
    let spaces = " ".repeat(inner.width as usize - left_part.len() - right_part.len() - 4);

    let header_line = Line::from(vec![
        Span::raw(left_part),
        Span::raw(spaces),
        Span::styled(format!("✔: {}", state.lessons_passed), Style::default().fg(Color::Indexed(2))),
        Span::raw(", "),
        Span::styled(format!("✘: {}", state.lessons_failed), Style::default().fg(Color::Indexed(1))),
        Span::raw("    "),
    ]);
    f.render_widget(Paragraph::new(header_line), header_area);
    y += 1;

    // Separator
    let sep_area2 = Rect::new(inner.x, y, inner.width, 1);
    f.render_widget(Paragraph::new(sep.clone()), sep_area2);
    y += 1;

    // Blank line
    y += 1;

    // Lesson text area
    // Build the lesson text spans
    let lesson_spans = build_lesson_spans_v2(state);
    let lesson_line = Line::from(lesson_spans);
    let lesson_text_area = Rect::new(inner.x, y, inner.width, 1);
    f.render_widget(Paragraph::new(lesson_line).alignment(Alignment::Center), lesson_text_area);
    y += 1;

    // Typed display area
    let typed_line = build_typed_line(state);
    let typed_area = Rect::new(inner.x, y, inner.width, 1);
    f.render_widget(Paragraph::new(typed_line).alignment(Alignment::Center), typed_area);
    y += 1;

    // Blank line
    y += 1;

    // Keyboard
    if !args.nokb {
        // Determine next char to highlight
        let next_char = if !state.lesson_complete && state.current_ngram_idx < state.lesson.len() {
            if state.needs_space {
                Some(' ')
            } else {
                state.lesson[state.current_ngram_idx]
                    .chars()
                    .nth(state.current_char_idx)
            }
        } else {
            None
        };

        // Map next_char through emulation if needed
        let display_char = if let Some(nc) = next_char {
            // In emulation mode, the DISPLAY shows the EMU_OUT char
            // but the user types EMU_IN char
            // The keyboard displayed is EMU_OUT layout
            // The key to highlight corresponds to nc in EMU_OUT layout
            Some(nc)
        } else {
            None
        };

        let kb_area = Rect::new(inner.x, y, inner.width, kb_height);
        if args.show_ortho {
            render_keyboard_ortho(f, kb_area, kb_layout, display_char);
        } else {
            render_keyboard_staggered(f, kb_area, kb_layout, display_char);
        }
        y += kb_height;
    }

    // Separator
    if inner.height > y - inner.y + 2 {
        let sep_area3 = Rect::new(inner.x, y, inner.width, 1);
        f.render_widget(Paragraph::new(sep.clone()), sep_area3);
        y += 1;

        // Stats
        let stats_y = y;

        // WPM line
        let wpm_line = Line::from(vec![
            Span::styled(
                format!("  need >= {:3}WPM,   avg. {:3}WPM,   last {:3}WPM", 
                    args.wpm, state.avg_wpm, state.last_wpm),
                Style::default().fg(Color::Indexed(7)),
            ),
        ]);

        // Actually need to color the actual values differently
        let wpm_line_colored = build_stats_line_wpm(state, args);
        let acc_line_colored = build_stats_line_acc(state, args);

        let stats_area = Rect::new(inner.x, stats_y, inner.width, 1);
        f.render_widget(Paragraph::new(wpm_line_colored), stats_area);

        if stats_y + 1 < inner.y + inner.height {
            let acc_area = Rect::new(inner.x, stats_y + 1, inner.width, 1);
            f.render_widget(Paragraph::new(acc_line_colored), acc_area);
        }
    }

    // Cat
    if args.cat {
        let cat_lines = vec![
            "/\\_/\\",
            ">(•༝• )<",
            "|    \\",
        ];
        // Position cat at bottom right of the stats area
        let cat_x = inner.x + inner.width - 12;
        let cat_y = inner.y + inner.height - 3;
        for (i, line) in cat_lines.iter().enumerate() {
            if cat_y + i as u16 < inner.y + inner.height {
                let cat_area = Rect::new(cat_x, cat_y + i as u16, 12, 1);
                f.render_widget(Paragraph::new(*line), cat_area);
            }
        }
    }
}

fn build_typed_line(state: &AppState) -> Line<'static> {
    if state.typed_display.is_empty() {
        return Line::from("");
    }

    Line::from(Span::styled(
        state.typed_display.clone(),
        Style::default().fg(Color::Indexed(7)).add_modifier(Modifier::ITALIC),
    ))
}

fn build_lesson_spans_v2(state: &AppState) -> Vec<Span<'static>> {
    let mut spans = Vec::new();

    for (i, ngram) in state.lesson.iter().enumerate() {
        if i > 0 {
            // Space separator between ngrams
            if state.ngram_completed[i-1] {
                // Replace space with bullet
                spans.push(Span::styled(
                    "•",
                    Style::default().fg(Color::Indexed(1)).add_modifier(Modifier::BOLD),
                ));
            } else {
                spans.push(Span::raw(" "));
            }
        }

        if state.ngram_completed[i] {
            // Completed: green or red
            let color = if state.ngram_errors[i] {
                Color::Indexed(1)
            } else {
                Color::Indexed(2)
            };
            spans.push(Span::styled(
                ngram.clone(),
                Style::default().fg(color).add_modifier(Modifier::BOLD),
            ));
        } else {
            // Not completed yet
            spans.push(Span::styled(
                ngram.clone(),
                Style::default().add_modifier(Modifier::BOLD),
            ));
        }
    }

    // If lesson complete, add trailing bullet
    if state.lesson_complete {
        spans.push(Span::styled(
            "•",
            Style::default().fg(Color::Indexed(1)).add_modifier(Modifier::BOLD),
        ));
    }

    spans
}

fn build_stats_line_wpm(state: &AppState, args: &Args) -> Line<'static> {
    let dim = Style::default().fg(Color::Indexed(7));
    let normal = Style::default().fg(Color::Indexed(15));

    Line::from(vec![
        Span::styled(format!("  need >= {:3}WPM,   avg.", args.wpm), dim),
        Span::styled(format!(" {:3}WPM", state.avg_wpm), normal),
        Span::styled(",   last", dim),
        Span::styled(format!(" {:3}WPM", state.last_wpm), normal),
    ])
}

fn build_stats_line_acc(state: &AppState, args: &Args) -> Line<'static> {
    let dim = Style::default().fg(Color::Indexed(7));
    let normal = Style::default().fg(Color::Indexed(15));

    Line::from(vec![
        Span::styled(format!("  need >= {:3}% Acc, avg.", args.acc), dim),
        Span::styled(format!(" {:3}% Acc", state.avg_acc), normal),
        Span::styled(", last", dim),
        Span::styled(format!(" {:3}% Acc", state.last_acc), normal),
    ])
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();

    // Setup terminal
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // Get ngram list
    let ngram_list = get_ngram_list(&args);

    // Generate first lesson
    let lesson = generate_lesson(&ngram_list, args.combi, args.rep);
    let mut state = AppState::new(lesson);

    let mut running = true;

    while running {
        // Draw
        terminal.draw(|f| render_ui(f, &state, &args))?;

        // Handle events
        if event::poll(Duration::from_millis(50))? {
            match event::read()? {
                Event::Key(KeyEvent { code, modifiers, .. }) => {
                    match code {
                        KeyCode::Esc => {
                            running = false;
                        }
                        KeyCode::Char('c') if modifiers.contains(KeyModifiers::CONTROL) => {
                            running = false;
                        }
                        KeyCode::Char(c) => {
                            if state.lesson_complete {
                                // Check if lesson passed or failed
                                if state.last_wpm >= args.wpm && state.last_acc >= args.acc {
                                    state.lessons_passed += 1;
                                } else {
                                    state.lessons_failed += 1;
                                }
                                state.lesson_num += 1;
                                // Generate new lesson
                                let lesson = generate_lesson(&ngram_list, args.combi, args.rep);
                                state.next_lesson(lesson);
                                // Process this char as first input of new lesson
                                // Map char through emulation
                                let mapped_c = map_char_for_emulation(c, &args.emu_in, &args.emu_out);
                                state.handle_char(mapped_c);
                            } else {
                                let mapped_c = map_char_for_emulation(c, &args.emu_in, &args.emu_out);
                                state.handle_char(mapped_c);
                            }
                        }
                        KeyCode::Backspace => {
                            // Ignore backspace
                        }
                        _ => {}
                    }
                }
                Event::Resize(_, _) => {}
                _ => {}
            }
        }
    }

    // Cleanup
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    Ok(())
}
