fn get_ngram_list(args: &Args) -> Vec<String> {
    match args.n.as_str() {
        "2" => {
            let all = data::BIGRAMS;
            let top = args.top.min(all.len());
            all[..top].iter().map(|s| s.to_string()).collect()
        }
        "3" => {
            let all = data::TRIGRAMS;
            let top = args.top.min(all.len());
            all[..top].iter().map(|s| s.to_string()).collect()
        }
        "4" => {
            let all = data::TETRAGRAMS;
            let top = args.top.min(all.len());
            all[..top].iter().map(|s| s.to_string()).collect()
        }
        "w" => {
            let all = data::WORDS;
            let top = args.top.min(all.len());
            all[..top].iter().map(|s| s.to_string()).collect()
        }
        filename => {
            // Try to read as file
            if let Ok(content) = std::fs::read_to_string(filename) {
                content.split(',')
                    .map(|s| s.trim().to_string())
                    .filter(|s| !s.is_empty())
                    .collect()
            } else {
                // Default to bigrams if file not found
                let all = data::BIGRAMS;
                let top = args.top.min(all.len());
                all[..top].iter().map(|s| s.to_string()).collect()
            }
        }
    }
}

fn generate_lesson(ngram_list: &[String], combi: usize, rep: usize) -> Vec<String> {
    let mut rng = rand::thread_rng();
    let combi = combi.min(ngram_list.len().max(1));

    // Pick `combi` ngrams randomly with replacement
    let mut selected: Vec<String> = (0..combi)
        .map(|_| ngram_list.choose(&mut rng).unwrap().clone())
        .collect();

    // Create lesson: each selected ngram repeated `rep` times, interleaved
    // The lesson format is: ng1 ng2 ng1 ng2 ... (rep times each, interleaved)
    let mut lesson = Vec::new();
    for _ in 0..rep {
        for ng in &selected {
            lesson.push(ng.clone());
        }
    }
    lesson
}

fn get_layout_key(c: char, layout: &str) -> Option<(usize, usize)> {
    // Returns (row, col) position of character in the given layout
    let rows: [&[char]; 3] = match layout {
        "qwerty" => &[
            &['q','w','e','r','t','y','u','i','o','p','[',']'],
            &['a','s','d','f','g','h','j','k','l',';','\''],
            &['z','x','c','v','b','n','m',',','.','/'],
        ],
        "qwertz" => &[
            &['q','w','e','r','t','z','u','i','o','p','[',']'],
            &['a','s','d','f','g','h','j','k','l',';','\''],
            &['y','x','c','v','b','n','m',',','.','/'],
        ],
        "azerty" => &[
            &['a','z','e','r','t','y','u','i','o','p','[',']'],
            &['q','s','d','f','g','h','j','k','l',';','\''],
            &['w','x','c','v','b','n','m',',','.','/'],
        ],
        "dvorak" => &[
            &['\'',',','.','p','y','f','g','c','r','l','/','='],
            &['a','o','e','u','i','d','h','t','n','s','-'],
            &[';','q','j','k','x','b','m','w','v','z'],
        ],
        "colemak" => &[
            &['q','w','f','p','g','j','l','u','y',';','[',']'],
            &['a','r','s','t','d','h','n','e','i','o','\''],
            &['z','x','c','v','b','k','m',',','.','/'],
        ],
        "colemakdh" => &[
            &['q','w','f','p','b','j','l','u','y',';','[',']'],
            &['a','r','s','t','g','m','n','e','i','o','\''],
            &['z','x','c','d','v','k','h',',','.','/'],
        ],
        _ => return None,
    };

    for (row_idx, row) in rows.iter().enumerate() {
        for (col_idx, &key) in row.iter().enumerate() {
            if key == c {
                return Some((row_idx, col_idx));
            }
        }
    }
    None
}

fn map_char_for_emulation(c: char, emu_in: &str, emu_out: &str) -> char {
    if emu_in.is_empty() || emu_out.is_empty() {
        return c;
    }

    // Find the position of c in emu_in layout
    if let Some((row, col)) = get_layout_key(c, emu_in) {
        // Map that position to the emu_out layout character
        let rows: [&[char]; 3] = match emu_out {
            "qwerty" => &[
                &['q','w','e','r','t','y','u','i','o','p','[',']'],
                &['a','s','d','f','g','h','j','k','l',';','\''],
                &['z','x','c','v','b','n','m',',','.','/'],
            ],
            "qwertz" => &[
                &['q','w','e','r','t','z','u','i','o','p','[',']'],
                &['a','s','d','f','g','h','j','k','l',';','\''],
                &['y','x','c','v','b','n','m',',','.','/'],
            ],
            "azerty" => &[
                &['a','z','e','r','t','y','u','i','o','p','[',']'],
                &['q','s','d','f','g','h','j','k','l',';','\''],
                &['w','x','c','v','b','n','m',',','.','/'],
            ],
            "dvorak" => &[
                &['\'',',','.','p','y','f','g','c','r','l','/','='],
                &['a','o','e','u','i','d','h','t','n','s','-'],
                &[';','q','j','k','x','b','m','w','v','z'],
            ],
            "colemak" => &[
                &['q','w','f','p','g','j','l','u','y',';','[',']'],
                &['a','r','s','t','d','h','n','e','i','o','\''],
                &['z','x','c','v','b','k','m',',','.','/'],
            ],
            "colemakdh" => &[
                &['q','w','f','p','b','j','l','u','y',';','[',']'],
                &['a','r','s','t','g','m','n','e','i','o','\''],
                &['z','x','c','d','v','k','h',',','.','/'],
            ],
            _ => return c,
        };

        if row < rows.len() && col < rows[row].len() {
            return rows[row][col];
        }
    }

    c
}

