            ["w", "x", "c", "v", "b", "n", "m", ",", ".", "/", " ", " "],
        ],
        "qwertz" => [
            ["q", "w", "e", "r", "t", "z", "u", "i", "o", "p", "[", "]"],
            ["a", "s", "d", "f", "g", "h", "j", "k", "l", ";", "'", " "],
            ["y", "x", "c", "v", "b", "n", "m", ",", ".", "/", " ", " "],
        ],
        // Default qwerty
        _ => [
            ["q", "w", "e", "r", "t", "y", "u", "i", "o", "p", "[", "]"],
            ["a", "s", "d", "f", "g", "h", "j", "k", "l", ";", "'", " "],
            ["z", "x", "c", "v", "b", "n", "m", ",", ".", "/", " ", " "],
        ],
    }
}

struct AppState {
    lesson_num: u32,
    lesson: Vec<String>,  // list of ngrams in current lesson
    // Current position in lesson:
    // current_ngram_idx: which ngram we're typing
    // current_char_idx: which char within the ngram
    current_ngram_idx: usize,
    current_char_idx: usize,
    // For display: what's been typed so far (including spaces)
    typed_display: String,
    // Error tracking per ngram (whether there was an error in the current ngram)
    ngram_had_error: bool,
    // Which ngrams had errors (for display coloring)
    ngram_errors: Vec<bool>,  // true = had error
    ngram_completed: Vec<bool>,
    // Timing
    lesson_start: Option<Instant>,
    // Stats
    lessons_passed: u32,
    lessons_failed: u32,
    // WPM tracking
    avg_wpm: u32,
    last_wpm: u32,
    avg_acc: u32,
    last_acc: u32,
    // Lesson complete
    lesson_complete: bool,
    lesson_passed: bool,
    // Error count for current lesson
    total_errors: u32,
    total_correct: u32,
    // Space needed flag (after ngram complete, need space before next)
    needs_space: bool,
}

impl AppState {
    fn new(lesson: Vec<String>) -> Self {
        let n = lesson.len();
        AppState {
            lesson_num: 1,
            lesson,
            current_ngram_idx: 0,
            current_char_idx: 0,
            typed_display: String::new(),
            ngram_had_error: false,
            ngram_errors: vec![false; n],
            ngram_completed: vec![false; n],
            lesson_start: None,
            lessons_passed: 0,
            lessons_failed: 0,
            avg_wpm: 0,
            last_wpm: 0,
            avg_acc: 0,
            last_acc: 0,
            lesson_complete: false,
            lesson_passed: false,
            total_errors: 0,
            total_correct: 0,
            needs_space: false,
        }
    }

    fn next_lesson(&mut self, lesson: Vec<String>) {
        let n = lesson.len();
        self.lesson = lesson;
        self.current_ngram_idx = 0;
        self.current_char_idx = 0;
        self.typed_display = String::new();
        self.ngram_had_error = false;
        self.ngram_errors = vec![false; n];
        self.ngram_completed = vec![false; n];
        self.lesson_start = None;
        self.lesson_complete = false;
        self.lesson_passed = false;
        self.total_errors = 0;
        self.total_correct = 0;
        self.needs_space = false;
    }

    fn handle_char(&mut self, c: char) {
        if self.lesson_complete {
            return;
        }

        if self.needs_space {
            // Expecting a space to advance to next ngram
            if c == ' ' {
                self.typed_display.push(' ');
                self.needs_space = false;
                // Already advanced ngram_idx in handle_ngram_complete
            }
            // Wrong key while expecting space: ignore
            return;
        }

        if self.current_ngram_idx >= self.lesson.len() {
            return;
        }

        // Start timer on first character
        if self.lesson_start.is_none() && self.current_char_idx == 0 && self.current_ngram_idx == 0 {
            self.lesson_start = Some(Instant::now());
        }

        let current_ngram = &self.lesson[self.current_ngram_idx];
        let expected = current_ngram.chars().nth(self.current_char_idx);

        if let Some(exp) = expected {
            if c == exp {
                // Correct
                self.total_correct += 1;
                self.typed_display.push(c);
                self.current_char_idx += 1;

                if self.current_char_idx >= current_ngram.len() {
                    // Ngram complete
                    self.ngram_completed[self.current_ngram_idx] = true;
                    self.ngram_errors[self.current_ngram_idx] = self.ngram_had_error;
                    self.ngram_had_error = false;
                    self.current_ngram_idx += 1;
                    self.current_char_idx = 0;

                    if self.current_ngram_idx >= self.lesson.len() {
                        // Lesson complete
                        self.complete_lesson();
                    } else {
                        // Need space before next ngram
                        self.needs_space = true;
                    }
                }
            } else {
                // Wrong character
                self.total_errors += 1;
                self.ngram_had_error = true;
                self.typed_display.push(c);  // show wrong char
            }
        }
    }

    fn complete_lesson(&mut self) {
        self.lesson_complete = true;

        // Calculate WPM
        if let Some(start) = self.lesson_start {
            let elapsed = start.elapsed();
            let seconds = elapsed.as_secs_f64();
            if seconds > 0.0 {
                // Count non-space chars typed
                let chars_typed: u32 = self.lesson.iter().map(|s| s.len() as u32).sum();
                let words = chars_typed as f64 / 5.0;
                let wpm = (words / (seconds / 60.0)) as u32;
                self.last_wpm = wpm;

                // Update avg WPM
                let total_lessons = self.lessons_passed + self.lessons_failed + 1;
                if total_lessons == 1 {
                    self.avg_wpm = wpm;
                } else {
                    self.avg_wpm = ((self.avg_wpm as u64 * (total_lessons - 1) as u64 
                                    + wpm as u64) / total_lessons as u64) as u32;
                }
            }
        }

        // Calculate accuracy
        let total_keystrokes = self.total_correct + self.total_errors;
        let acc = if total_keystrokes > 0 {
            (self.total_correct as f64 / (self.total_correct + self.total_errors) as f64 * 100.0) as u32
        } else {
            100
        };
        self.last_acc = acc;

        let total_lessons = self.lessons_passed + self.lessons_failed + 1;
        if total_lessons == 1 {
            self.avg_acc = acc;
        } else {
            self.avg_acc = ((self.avg_acc as u64 * (total_lessons - 1) as u64 
                             + acc as u64) / total_lessons as u64) as u32;
        }
    }
}

fn build_lesson_spans<'a>(state: &AppState) -> Vec<Span<'a>> {
    let mut spans = Vec::new();

    for (i, ngram) in state.lesson.iter().enumerate() {
        if i > 0 {
            // Space separator
            if state.ngram_completed[i-1] {
                // Completed ngram: show bullet in cyan/yellow
                spans.push(Span::styled(
                    "•",
                    Style::default().fg(Color::Indexed(1)).add_modifier(Modifier::BOLD),
                ));
            } else {
                spans.push(Span::raw(" "));
            }
        }

        if state.ngram_completed[i] {
            // Completed ngram - show in green (no error) or red (with error)
            let color = if state.ngram_errors[i] {
                Color::Indexed(1)  // red for errors
            } else {
                Color::Indexed(2)  // green for clean
            };
            spans.push(Span::styled(
                ngram.clone(),
                Style::default().fg(color).add_modifier(Modifier::BOLD),
            ));
        } else if i == state.current_ngram_idx {
            // Currently being typed
            // Show typed chars in green/red, remaining in default
            let ngram_chars: Vec<char> = ngram.chars().collect();

            // Already typed chars in this ngram
            if state.current_char_idx > 0 {
                // The chars typed so far are in typed_display
                // Just show the whole ngram for simplicity
                // Actually we need to show typed chars differently
                // For now, show the whole ngram
            }

            // Show the ngram text  
            spans.push(Span::styled(
                ngram.clone(),
                Style::default().add_modifier(Modifier::BOLD),
            ));
        } else {
            // Future ngram
            spans.push(Span::raw(ngram.clone()));
        }
    }

    // Trailing bullet if lesson complete
    if state.lesson_complete {
        if let Some(last) = state.lesson.last() {
            let _ = last; // already handled above
        }
        spans.push(Span::styled(
            "•",
            Style::default().fg(Color::Indexed(1)).add_modifier(Modifier::BOLD),
        ));
    }

    spans
}

fn render_keyboard_staggered(
    f: &mut Frame,
    area: Rect,
    layout_keys: [[&str; 12]; 3],
    next_char: Option<char>,
) {
    // 12 keys * 4 chars each = 48 chars + 1 for last
    // Row 1: ┌───┬───┬...┬───┐
    // Row 2: │ q │ w │...│ ] │
    // etc.

    let style_normal = Style::default().fg(Color::Indexed(7));
    let style_highlight = Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD);

    // Find which key to highlight
    let highlight_row_col: Option<(usize, usize)> = if let Some(nc) = next_char {
        let rows: [[&str; 12]; 3] = layout_keys;
        let mut found = None;
        'outer: for (ri, row) in rows.iter().enumerate() {
            for (ci, key) in row.iter().enumerate() {
                if key.len() == 1 {
                    if key.chars().next() == Some(nc) {
                        found = Some((ri, ci));
                        break 'outer;
                    }
                }
            }
        }
        found
    } else {
        None
    };

    // Actually for the keyboard rendering, let me use a simple text approach
    // The keyboard has a specific visual layout that I need to replicate

    // Let me render using a Paragraph with pre-built text
    let row0 = &layout_keys[0];
    let row1 = &layout_keys[1];
    let row2 = &layout_keys[2];

    // Count keys per row (non-empty keys)
    let row0_keys: Vec<&str> = row0.iter().filter(|&&k| k != " ").copied().collect();
    let row1_keys: Vec<&str> = row1.iter().filter(|&&k| k != " ").copied().collect();
    let row2_keys: Vec<&str> = row2.iter().filter(|&&k| k != " ").copied().collect();

    // Build keyboard lines with boxes
    // Row 0: ┌───┬───┬...┬───┐
    // Row 0 content: │ q │ w │...│ ] │
    // Row 0 bottom / Row 1 top: └┬──┴┬──┴...┬──┘ (with offsets for stagger)
    // Row 1 content: │ a │ s │...│ ' │
    // Row 1 bottom / Row 2 top: └┬──┴┬──┴...┬──┘
    // Row 2 content: │ z │ x │...│ / │
    // Row 2 bottom: └───┴───┴...┴───┘

    // For staggered layout, rows 1 and 2 are offset by 1 and 2 chars respectively
    let offset = 14; // padding from left

    let build_top_row = |n: usize| -> String {
        let mut s = String::new();
        s.push('┌');
        for i in 0..n {
            s.push_str("───");
            if i < n - 1 { s.push('┬'); }
        }
        s.push('┐');
        s
    };

    let build_content_row = |keys: &[&str], highlight: Option<usize>| -> Vec<Span<'static>> {
        let mut spans = Vec::new();
        spans.push(Span::styled("│", Style::default().fg(Color::Indexed(7))));
        for (i, key) in keys.iter().enumerate() {
            let content = format!(" {} ", key);
            if let Some(hi) = highlight {
                if i == hi {
                    spans.push(Span::styled(content, Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD)));
                } else {
                    spans.push(Span::styled(content, Style::default().fg(Color::Indexed(7))));
                }
            } else {
                spans.push(Span::styled(content, Style::default().fg(Color::Indexed(7))));
            }
            spans.push(Span::styled("│", Style::default().fg(Color::Indexed(7))));
        }
        spans
    };

    let build_bottom_to_next_row = |n_top: usize, n_bot: usize| -> String {
        // └┬──┴┬──┴...
        let mut s = String::new();
        s.push('└');
        // This is complex stagger logic, simplified here
        for i in 0..n_top.max(n_bot) {
            if i < n_top - 1 {
                s.push_str("┬──┴");
            }
        }
        s.push('┘');
        s
    };

    // For simplicity, use pre-built keyboard string 
    // Standard QWERTY keyboard layout drawing:
    let (r0h, r1h, r2h) = match highlight_row_col {
        Some((0, c)) => (Some(c), None, None),
        Some((1, c)) => (None, Some(c), None),
        Some((2, c)) => (None, None, Some(c)),
        _ => (None, None, None),
    };

    // Build the keyboard lines
    let n0 = row0_keys.len();
    let n1 = row1_keys.len();
    let n2 = row2_keys.len();

    let indent0 = " ".repeat(offset);
    let indent1 = " ".repeat(offset + 1);
    let indent2 = " ".repeat(offset + 2);

    // Row 0 top border
    let mut top_line = format!("{}┌", indent0);
    for i in 0..n0 {
        top_line.push_str("───");
        if i < n0 - 1 { top_line.push('┬'); }
    }
    top_line.push('┐');

    // Row 0 content
    // Row 0 middle/bottom (staggered join with row 1)
    let mut mid01_line = format!("{}└", indent0);
    for i in 0..n0 {
        mid01_line.push('┬');
        mid01_line.push_str("──");
        if i < n0 - 1 { mid01_line.push('┴'); }
    }
    mid01_line.push('┘');

    // Row 1 middle/bottom
    let mut mid12_line = format!("{}└", indent1);
    for i in 0..n1 {
        mid12_line.push('┬');
        mid12_line.push_str("──");
        if i < n1 - 1 { mid12_line.push('┴'); }
    }
    mid12_line.push('┘');

    // Row 2 bottom
    let mut bot_line = format!("{}└", indent2);
    for i in 0..n2 {
        bot_line.push_str("───");
        if i < n2 - 1 { bot_line.push('┴'); }
    }
    bot_line.push('┘');

    // Now render each line
    let lines_count = 7;
    let y_start = area.y + (area.height.saturating_sub(lines_count)) / 2;

    if y_start + lines_count > area.y + area.height {
        return;
    }

    // We'll render as a Paragraph instead
    let mut kb_lines = Vec::new();

    kb_lines.push(Line::from(vec![Span::styled(top_line, Style::default().fg(Color::Indexed(7)))]));

    // Row 0 content line
    let mut row0_line = vec![Span::styled(indent0.clone() + "│", Style::default().fg(Color::Indexed(7)))];
    for (i, key) in row0_keys.iter().enumerate() {
        let content = format!(" {} ", key);
        let style = if r0h == Some(i) {
            Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::Indexed(7))
        };
        row0_line.push(Span::styled(content, style));
        row0_line.push(Span::styled("│", Style::default().fg(Color::Indexed(7))));
    }
    kb_lines.push(Line::from(row0_line));

    kb_lines.push(Line::from(vec![Span::styled(mid01_line, Style::default().fg(Color::Indexed(7)))]));

    // Row 1 content line
    let mut row1_line = vec![Span::styled(indent1.clone() + "│", Style::default().fg(Color::Indexed(7)))];
    for (i, key) in row1_keys.iter().enumerate() {
        let content = format!(" {} ", key);
        let style = if r1h == Some(i) {
            Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::Indexed(7))
        };
        row1_line.push(Span::styled(content, style));
        row1_line.push(Span::styled("│", Style::default().fg(Color::Indexed(7))));
    }
    kb_lines.push(Line::from(row1_line));

    kb_lines.push(Line::from(vec![Span::styled(mid12_line, Style::default().fg(Color::Indexed(7)))]));

    // Row 2 content line
    let mut row2_line = vec![Span::styled(indent2.clone() + "│", Style::default().fg(Color::Indexed(7)))];
    for (i, key) in row2_keys.iter().enumerate() {
        let content = format!(" {} ", key);
        let style = if r2h == Some(i) {
            Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::Indexed(7))
        };
        row2_line.push(Span::styled(content, style));
        row2_line.push(Span::styled("│", Style::default().fg(Color::Indexed(7))));
    }
    kb_lines.push(Line::from(row2_line));

    kb_lines.push(Line::from(vec![Span::styled(bot_line, Style::default().fg(Color::Indexed(7)))]));

    let para = Paragraph::new(kb_lines);
    f.render_widget(para, area);
}

fn render_keyboard_ortho(
    f: &mut Frame,
    area: Rect,
    layout_keys: [[&str; 12]; 3],
    next_char: Option<char>,
) {
    let offset = 13; // padding from left
    let indent = " ".repeat(offset);

    let (r0h, r1h, r2h) = if let Some(nc) = next_char {
        let mut found = (None, None, None);
        'outer: for (ri, row) in layout_keys.iter().enumerate() {
            for (ci, key) in row.iter().enumerate() {
                if key.len() == 1 && key.chars().next() == Some(nc) {
                    match ri {
                        0 => found.0 = Some(ci),
                        1 => found.1 = Some(ci),
                        2 => found.2 = Some(ci),
                        _ => {}
                    }
                    break 'outer;
                }
            }
        }
        found
    } else {
        (None, None, None)
    };

    let n = 12; // fixed 12 columns for ortho

    let build_top = || -> String {
        let mut s = format!("{indent}┌");
        for i in 0..n {
            s.push_str("───");
            if i < n - 1 { s.push('┬'); }
        }
        s.push('┐');
        s
    };

    let build_mid = || -> String {
        let mut s = format!("{indent}├");
        for i in 0..n {
            s.push_str("───");
            if i < n - 1 { s.push('┼'); }
        }
        s.push('┤');
        s
    };

    let build_bot = || -> String {
        let mut s = format!("{indent}└");
        for i in 0..n {
            s.push_str("───");
            if i < n - 1 { s.push('┴'); }
        }
        s.push('┘');
        s
    };

    let mut kb_lines = Vec::new();

    kb_lines.push(Line::from(Span::styled(build_top(), Style::default().fg(Color::Indexed(7)))));

    // Row 0
    let mut row0_line = vec![Span::styled(format!("{indent}│"), Style::default().fg(Color::Indexed(7)))];
    for i in 0..n {
        let key = layout_keys[0][i];
        let content = format!(" {} ", if key == " " { "△" } else { key });
        let style = if r0h == Some(i) && key != " " {
            Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD)
        } else if key == " " {
            Style::default().fg(Color::Indexed(8))
        } else {
            Style::default().fg(Color::Indexed(7))
        };
        row0_line.push(Span::styled(content, style));
        row0_line.push(Span::styled("│", Style::default().fg(Color::Indexed(7))));
    }
    kb_lines.push(Line::from(row0_line));

    kb_lines.push(Line::from(Span::styled(build_mid(), Style::default().fg(Color::Indexed(7)))));

    // Row 1
    let mut row1_line = vec![Span::styled(format!("{indent}│"), Style::default().fg(Color::Indexed(7)))];
    for i in 0..n {
        let key = layout_keys[1][i];
        let content = format!(" {} ", if key == " " { "△" } else { key });
        let style = if r1h == Some(i) && key != " " {
            Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD)
        } else if key == " " {
            Style::default().fg(Color::Indexed(8))
        } else {
            Style::default().fg(Color::Indexed(7))
        };
        row1_line.push(Span::styled(content, style));
        row1_line.push(Span::styled("│", Style::default().fg(Color::Indexed(7))));
    }
    kb_lines.push(Line::from(row1_line));

    kb_lines.push(Line::from(Span::styled(build_mid(), Style::default().fg(Color::Indexed(7)))));

    // Row 2
    let mut row2_line = vec![Span::styled(format!("{indent}│"), Style::default().fg(Color::Indexed(7)))];
    for i in 0..n {
        let key = layout_keys[2][i];
        let content = format!(" {} ", if key == " " { "△" } else { key });
        let style = if r2h == Some(i) && key != " " {
            Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD)
        } else if key == " " {
            Style::default().fg(Color::Indexed(8))
        } else {
            Style::default().fg(Color::Indexed(7))
        };
        row2_line.push(Span::styled(content, style));
        row2_line.push(Span::styled("│", Style::default().fg(Color::Indexed(7))));
    }
    kb_lines.push(Line::from(row2_line));

    kb_lines.push(Line::from(Span::styled(build_bot(), Style::default().fg(Color::Indexed(7)))));

    let para = Paragraph::new(kb_lines);
    f.render_widget(para, area);
}

fn render_ui(f: &mut Frame, state: &AppState, args: &Args) {
    let size = f.area();

    // Minimum size check
    let min_width = 80;
    let min_height = 13;
    if size.width < min_width || size.height < min_height {
        let msg = format!(
            "Please resize your terminal to at least {}x{}.",
            min_width, min_height
        );
        let p = Paragraph::new(vec![
            Line::from(""),
            Line::from(Span::raw(msg)),
            Line::from(""),
            Line::from("             <esc> or <ctrl-c> to quit"),
        ]);
        f.render_widget(p, size);
        return;
    }

    // Outer block
    let outer_block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default())
        .title(Span::styled(
            " Quit <esc> ",
            Style::default().fg(Color::Indexed(4)).add_modifier(Modifier::BOLD),
        ))
        .title_alignment(Alignment::Right);

    let inner = outer_block.inner(size);
    f.render_widget(outer_block, size);

    // Title line
    let title_line = Line::from(vec![
        Span::styled("ngrrram!", Style::default().add_modifier(Modifier::BOLD)),
        Span::styled("   by winterveil", Style::default().fg(Color::Indexed(7)).add_modifier(Modifier::ITALIC)),
    ]);

    // Separator
    let sep = "─".repeat(inner.width as usize);

    // Header: Lesson number and stats
    let lesson_header = Line::from(vec![
        Span::raw(format!("    Lesson #{}", state.lesson_num)),
        Span::raw(" ".repeat(inner.width as usize - 
            format!("    Lesson #{}", state.lesson_num).len() - 
            format!("✔: {}, ✘: {}", state.lessons_passed, state.lessons_failed).len() - 4)),
        Span::styled(format!("✔: {}", state.lessons_passed), Style::default().fg(Color::Indexed(2))),
        Span::raw(", "),
        Span::styled(format!("✘: {}", state.lessons_failed), Style::default().fg(Color::Indexed(1))),
        Span::raw("    "),
    ]);

    // Determine keyboard layout to show
    let kb_layout_name = if !args.emu_out.is_empty() {
        args.emu_out.as_str()
    } else {
        "qwerty"
    };
    let kb_layout = get_keyboard_layout(kb_layout_name);

    // Keyboard height
    let kb_height = if args.nokb { 0 } else { 7u16 };

    // Build layout constraints
    let needs_cat = args.cat;

    // Calculate areas
    // Title: 1 line
    // Sep: 1 line  
    // Header: 1 line
    // Sep: 1 line
    // Blank: 1 line
    // Lesson text: 1 line
    // Typed: 1 line
    // Blank: 1 line
    // KB: 7 lines (if shown)
    // Sep: 1 line
    // Stats: 2 lines

    let mut y = inner.y;

    // Title
    let title_area = Rect::new(inner.x, y, inner.width, 1);
    let title_para = Paragraph::new(title_line).alignment(Alignment::Center);
    f.render_widget(title_para, title_area);
    y += 1;

    // Separator
    let sep_area = Rect::new(inner.x, y, inner.width, 1);
    f.render_widget(Paragraph::new(sep.clone()), sep_area);
    y += 1;

    // Header line
    let header_area = Rect::new(inner.x, y, inner.width, 1);

    let right_part = format!("✔: {}, ✘: {}", state.lessons_passed, state.lessons_failed);
    let left_part = format!("    Lesson #{}", state.lesson_num);
    let spaces = " ".repeat(inner.width as usize - left_part.len() - right_part.len() - 4);

    let header_line = Line::from(vec![
        Span::raw(left_part),
        Span::raw(spaces),
        Span::styled(format!("✔: {}", state.lessons_passed), Style::default().fg(Color::Indexed(2))),
        Span::raw(", "),
        Span::styled(format!("✘: {}", state.lessons_failed), Style::default().fg(Color::Indexed(1))),
        Span::raw("    "),
    ]);
    f.render_widget(Paragraph::new(header_line), header_area);
    y += 1;

    // Separator
    let sep_area2 = Rect::new(inner.x, y, inner.width, 1);
    f.render_widget(Paragraph::new(sep.clone()), sep_area2);
    y += 1;

    // Blank line
    y += 1;

    // Lesson text area
    // Build the lesson text spans
    let lesson_spans = build_lesson_spans_v2(state);
    let lesson_line = Line::from(lesson_spans);
    let lesson_text_area = Rect::new(inner.x, y, inner.width, 1);
    f.render_widget(Paragraph::new(lesson_line).alignment(Alignment::Center), lesson_text_area);
    y += 1;

    // Typed display area
    let typed_line = build_typed_line(state);
    let typed_area = Rect::new(inner.x, y, inner.width, 1);
    f.render_widget(Paragraph::new(typed_line).alignment(Alignment::Center), typed_area);
    y += 1;

    // Blank line
    y += 1;

    // Keyboard
    if !args.nokb {
        // Determine next char to highlight
        let next_char = if !state.lesson_complete && state.current_ngram_idx < state.lesson.len() {
            if state.needs_space {
                Some(' ')
            } else {
                state.lesson[state.current_ngram_idx]
                    .chars()
                    .nth(state.current_char_idx)
            }
        } else {
            None
        };

        // Map next_char through emulation if needed
        let display_char = if let Some(nc) = next_char {
            // In emulation mode, the DISPLAY shows the EMU_OUT char
            // but the user types EMU_IN char
            // The keyboard displayed is EMU_OUT layout
            // The key to highlight corresponds to nc in EMU_OUT layout
            Some(nc)
        } else {
            None
        };

        let kb_area = Rect::new(inner.x, y, inner.width, kb_height);
        if args.show_ortho {
            render_keyboard_ortho(f, kb_area, kb_layout, display_char);
        } else {
            render_keyboard_staggered(f, kb_area, kb_layout, display_char);
        }
        y += kb_height;
    }

    // Separator
    if inner.height > y - inner.y + 2 {
        let sep_area3 = Rect::new(inner.x, y, inner.width, 1);
        f.render_widget(Paragraph::new(sep.clone()), sep_area3);
        y += 1;

        // Stats
        let stats_y = y;

        // WPM line
        let wpm_line = Line::from(vec![
            Span::styled(
                format!("  need >= {:3}WPM,   avg. {:3}WPM,   last {:3}WPM", 
                    args.wpm, state.avg_wpm, state.last_wpm),
                Style::default().fg(Color::Indexed(7)),
            ),
        ]);

        // Actually need to color the actual values differently
        let wpm_line_colored = build_stats_line_wpm(state, args);
        let acc_line_colored = build_stats_line_acc(state, args);

        let stats_area = Rect::new(inner.x, stats_y, inner.width, 1);
        f.render_widget(Paragraph::new(wpm_line_colored), stats_area);

