fn map_char_for_emulation(c: char, emu_in: &str, emu_out: &str) -> char {
    if emu_in.is_empty() || emu_out.is_empty() {
        return c;
    }

    let layout_rows = |name: &str| -> Vec<Vec<char>> {
        match name {
            "qwerty" => vec![
                "qwertyuiop[]".chars().collect(),
                "asdfghjkl;'".chars().collect(),
                "zxcvbnm,./".chars().collect(),
