            ["a", "r", "s", "t", "d", "h", "n", "e", "i", "o", "'", ""],
            ["z", "x", "c", "v", "b", "k", "m", ",", ".", "/", "", ""],
        ],
        "colemakdh" => [
            ["q", "w", "f", "p", "b", "j", "l", "u", "y", ";", "[", "]"],
            ["a", "r", "s", "t", "g", "m", "n", "e", "i", "o", "'", ""],
            ["z", "x", "c", "d", "v", "k", "h", ",", ".", "/", "", ""],
        ],
        "azerty" => [
            ["a", "z", "e", "r", "t", "y", "u", "i", "o", "p", "[", "]"],
            ["q", "s", "d", "f", "g", "h", "j", "k", "l", ";", "'", ""],
            ["w", "x", "c", "v", "b", "n", "m", ",", ".", "/", "", ""],
        ],
        "qwertz" => [
            ["q", "w", "e", "r", "t", "z", "u", "i", "o", "p", "[", "]"],
