fn generate_lesson(ngram_list: &[String], combi: usize, rep: usize) -> Vec<String> {
    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash, Hasher};
    use std::time::SystemTime;

    // Simple random using system time
    let now = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default()
        .subsec_nanos();

    let combi = combi.min(ngram_list.len().max(1));

    // Pick combi ngrams randomly with replacement
    let mut selected = Vec::new();
    let mut seed = now as u64;
    for _ in 0..combi {
        let idx = (seed as usize) % ngram_list.len();
        selected.push(ngram_list[idx].clone());
        // Simple LCG
        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
    }

    // Interleave: rep times each
    let mut lesson = Vec::new();
    for _ in 0..rep {
        for ng in &selected {
            lesson.push(ng.clone());
        }
    }
    lesson
}

struct AppState {
    lesson_num: u32,
    lesson: Vec<String>,
    current_ngram_idx: usize,
    current_char_idx: usize,
    typed_display: String,
    ngram_had_error: bool,
    ngram_errors: Vec<bool>,
    ngram_completed: Vec<bool>,
    lesson_start: Option<Instant>,
    lessons_passed: u32,
    lessons_failed: u32,
    avg_wpm: u32,
    last_wpm: u32,
    avg_acc: u32,
    last_acc: u32,
    lesson_complete: bool,
    total_errors: u32,
    total_correct: u32,
    needs_space: bool,
}

impl AppState {
    fn new(lesson: Vec<String>) -> Self {
        let n = lesson.len();
        AppState {
            lesson_num: 1,
            lesson,
            current_ngram_idx: 0,
            current_char_idx: 0,
            typed_display: String::new(),
            ngram_had_error: false,
            ngram_errors: vec![false; n],
            ngram_completed: vec![false; n],
            lesson_start: None,
            lessons_passed: 0,
            lessons_failed: 0,
            avg_wpm: 0,
            last_wpm: 0,
            avg_acc: 0,
            last_acc: 0,
            lesson_complete: false,
            total_errors: 0,
            total_correct: 0,
            needs_space: false,
        }
    }

    fn next_lesson(&mut self, lesson: Vec<String>) {
        let n = lesson.len();
        self.lesson = lesson;
        self.current_ngram_idx = 0;
        self.current_char_idx = 0;
        self.typed_display = String::new();
        self.ngram_had_error = false;
        self.ngram_errors = vec![false; n];
        self.ngram_completed = vec![false; n];
        self.lesson_start = None;
        self.lesson_complete = false;
        self.total_errors = 0;
        self.total_correct = 0;
        self.needs_space = false;
    }

    fn handle_char(&mut self, c: char) {
        if self.lesson_complete {
            return;
        }

        if self.needs_space {
            if c == ' ' {
                self.typed_display.push(' ');
                self.needs_space = false;
            }
            return;
        }

        if self.current_ngram_idx >= self.lesson.len() {
            return;
        }

        // Start timer on first character
        if self.lesson_start.is_none() {
            self.lesson_start = Some(Instant::now());
        }

        let current_ngram = &self.lesson[self.current_ngram_idx];
        let expected_char = current_ngram.chars().nth(self.current_char_idx);

        if let Some(exp) = expected_char {
            if c == exp {
                self.total_correct += 1;
                self.typed_display.push(c);
                self.current_char_idx += 1;

                if self.current_char_idx >= current_ngram.len() {
                    self.ngram_completed[self.current_ngram_idx] = true;
                    self.ngram_errors[self.current_ngram_idx] = self.ngram_had_error;
                    self.ngram_had_error = false;
                    self.current_ngram_idx += 1;
                    self.current_char_idx = 0;

                    if self.current_ngram_idx >= self.lesson.len() {
                        self.complete_lesson();
                    } else {
                        self.needs_space = true;
                    }
                }
            } else {
                self.total_errors += 1;
                self.ngram_had_error = true;
                self.typed_display.push(c);
            }
        }
    }

    fn complete_lesson(&mut self) {
        self.lesson_complete = true;

        if let Some(start) = self.lesson_start {
            let elapsed = start.elapsed();
            let seconds = elapsed.as_secs_f64();
            if seconds > 0.0 {
                let chars_typed: u32 = self.lesson.iter().map(|s| s.len() as u32).sum();
                let words = chars_typed as f64 / 5.0;
                let wpm = (words / (seconds / 60.0)) as u32;
                self.last_wpm = wpm;

                let total_lessons_done = self.lessons_passed + self.lessons_failed;
                if total_lessons_done == 0 {
                    self.avg_wpm = wpm;
                } else {
                    self.avg_wpm = ((self.avg_wpm as u64 * total_lessons_done as u64 
                                    + wpm as u64) / (total_lessons_done + 1) as u64) as u32;
                }
            }
        }

        let total_keystrokes = self.total_correct + self.total_errors;
        let acc = if total_keystrokes > 0 {
            (self.total_correct as f64 / total_keystrokes as f64 * 100.0) as u32
        } else {
            100
        };
        self.last_acc = acc;

        let total_lessons_done = self.lessons_passed + self.lessons_failed;
        if total_lessons_done == 0 {
            self.avg_acc = acc;
        } else {
            self.avg_acc = ((self.avg_acc as u64 * total_lessons_done as u64 
                             + acc as u64) / (total_lessons_done + 1) as u64) as u32;
        }
    }
}

// ANSI escape code helpers
const RESET: &str = "\x1b[0m";
