    write!(out, "\x1b[2J\x1b[H").ok();
}

fn goto(out: &mut impl Write, row: u16, col: u16) {
    write!(out, "\x1b[{};{}H", row + 1, col + 1).ok();
}

fn write_str(out: &mut impl Write, s: &str) {
