    let title_by = "   by winterveil";
    let title = format!("{}{}{}{}{}", BOLD, title_ngrrram, RESET, ITALIC, GRAY);
    // Center the title
    let visible_title_len = title_ngrrram.len() + title_by.len();
    let padding = (inner_width as usize).saturating_sub(visible_title_len) / 2;
    write!(out, "{}", " ".repeat(padding)).ok();
    write!(out, "{}{}{}", BOLD, title_ngrrram, RESET).ok();
    write!(out, "{}{}{}{}", ITALIC, GRAY, title_by, RESET).ok();
    let right_pad = inner_width as usize - padding - visible_title_len;
    write!(out, "{}", " ".repeat(right_pad)).ok();
    write!(out, "│").ok();

    // Separator
    goto(out, 2, 0);
    write!(out, "│{}│", "─".repeat(inner_width as usize)).ok();

    // Header: Lesson #N  ✔: 0, ✘: 0
    goto(out, 3, 0);
    write!(out, "│").ok();
    let left_header = format!("    Lesson #{}", state.lesson_num);
    let check_str = format!("✔: {}", state.lessons_passed);
    let x_str = format!("✘: {}", state.lessons_failed);
    let right_header = format!("{}, {}    ", check_str, x_str);
    let right_visible_len = check_str.len() + 2 + x_str.len() + 4; // ", " + "    "
    let mid_spaces = inner_width as usize - left_header.len() - right_visible_len;
    write!(out, "{}", left_header).ok();
    write!(out, "{}", " ".repeat(mid_spaces)).ok();
    write!(out, "{}{}{}", GREEN, check_str, RESET).ok();
    write!(out, ", ").ok();
    write!(out, "{}{}{}", RED, x_str, RESET).ok();
    write!(out, "    │").ok();

    // Separator
    goto(out, 4, 0);
    write!(out, "│{}│", "─".repeat(inner_width as usize)).ok();

    // Empty line
    goto(out, 5, 0);
    write!(out, "│{}│", " ".repeat(inner_width as usize)).ok();

    // Lesson text line (centered)
    goto(out, 6, 0);
    write!(out, "│").ok();

    // Build lesson text
    let mut lesson_text = String::new();
    let mut lesson_colored = String::new();

    for (i, ngram) in state.lesson.iter().enumerate() {
        if i > 0 {
            if state.ngram_completed[i-1] {
                lesson_text.push('•');
                lesson_colored.push_str(&format!("{}{}•{}", BOLD, RED, RESET));
            } else {
                lesson_text.push(' ');
                lesson_colored.push(' ');
            }
        }

        if state.ngram_completed[i] {
            let color = if state.ngram_errors[i] { RED } else { GREEN };
            lesson_colored.push_str(&format!("{}{}{}{}", BOLD, color, ngram, RESET));
            lesson_text.push_str(ngram);
        } else {
            lesson_colored.push_str(&format!("{}{}{}", BOLD, ngram, RESET));
            lesson_text.push_str(ngram);
        }
    }

    if state.lesson_complete {
        lesson_colored.push_str(&format!("{}{}•{}", BOLD, RED, RESET));
        lesson_text.push('•');
    }

    // Count visible length (without escape codes)
    let visible_len = lesson_text.chars().count();
    let text_padding = (inner_width as usize).saturating_sub(visible_len) / 2;
    let right_pad = inner_width as usize - text_padding - visible_len;

    write!(out, "{}", " ".repeat(text_padding)).ok();
    write!(out, "{}", lesson_colored).ok();
    write!(out, "{}", " ".repeat(right_pad)).ok();
    write!(out, "│").ok();

    // Typed text line (centered)
    goto(out, 7, 0);
    write!(out, "│").ok();

    let typed_text = &state.typed_display;
    let typed_visible = typed_text.chars().count();
    let typed_padding = (inner_width as usize).saturating_sub(typed_visible) / 2;
    let typed_right_pad = inner_width as usize - typed_padding - typed_visible;

    write!(out, "{}", " ".repeat(typed_padding)).ok();
    if !typed_text.is_empty() {
        write!(out, "{}{}{}{}", ITALIC, GRAY, typed_text, RESET).ok();
    }
    write!(out, "{}", " ".repeat(typed_right_pad)).ok();
    write!(out, "│").ok();

    let mut next_row = 8u16;

    // Keyboard display
    if !args.nokb {
        // Empty line before keyboard
        goto(out, next_row, 0);
        write!(out, "│{}│", " ".repeat(inner_width as usize)).ok();
        next_row += 1;

        let kb_layout_name = if !args.emu_out.is_empty() {
            args.emu_out.as_str()
        } else {
            "qwerty"
        };
        let kb_keys = get_keyboard_display_keys(kb_layout_name);

        // Determine next char for highlighting
        let next_char = if !state.lesson_complete && state.current_ngram_idx < state.lesson.len() {
            if state.needs_space {
                None // don't highlight for space
            } else {
                state.lesson[state.current_ngram_idx]
                    .chars()
                    .nth(state.current_char_idx)
            }
        } else {
            None
        };

        let highlight_pos = next_char.and_then(|c| find_key_position(c, &kb_keys));

        if args.show_ortho {
            render_kb_ortho(out, next_row, width, &kb_keys, highlight_pos);
            next_row += 5;
        } else {
            render_kb_staggered(out, next_row, width, &kb_keys, highlight_pos);
            next_row += 7;
        }
    } else {
        // Two empty lines (matching with-keyboard height more or less)
        goto(out, next_row, 0);
        write!(out, "│{}│", " ".repeat(inner_width as usize)).ok();
        next_row += 1;
        goto(out, next_row, 0);
        write!(out, "│{}│", " ".repeat(inner_width as usize)).ok();
        next_row += 1;
    }

    // Separator before stats
    goto(out, next_row, 0);
    write!(out, "│{}│", "─".repeat(inner_width as usize)).ok();
    next_row += 1;

    // WPM stats line
    goto(out, next_row, 0);
    write!(out, "│").ok();
    render_stats_wpm(out, state, args, inner_width as usize);
    write!(out, "│").ok();
    next_row += 1;

    // Accuracy stats line
    goto(out, next_row, 0);
    write!(out, "│").ok();

    // Cat in bottom right of stats area
    if args.cat {
        render_stats_acc_with_cat(out, state, args, inner_width as usize, next_row);
    } else {
        render_stats_acc(out, state, args, inner_width as usize);
        write!(out, "│").ok();
    }
    next_row += 1;

    // Bottom border
    goto(out, next_row, 0);
    write!(out, "╰{}╯", "─".repeat(inner_width as usize)).ok();

    out.flush().ok();
}

