fn map_char_for_emulation(c: char, emu_in: &str, emu_out: &str) -> char {
    if emu_in.is_empty() || emu_out.is_empty() {
        return c;
    }

    let layout_rows = |name: &str| -> Vec<Vec<char>> {
        match name {
            "qwerty" => vec![
                "qwertyuiop[]".chars().collect(),
                "asdfghjkl;'".chars().collect(),
                "zxcvbnm,./".chars().collect(),
            ],
            "qwertz" => vec![
                "qwertzuiop[]".chars().collect(),
                "asdfghjkl;'".chars().collect(),
                "yxcvbnm,./".chars().collect(),
            ],
            "azerty" => vec![
                "azertyuiop[]".chars().collect(),
                "qsdfghjkl;'".chars().collect(),
                "wxcvbnm,./".chars().collect(),
            ],
            "dvorak" => vec![
                "',.pyfgcrl/=".chars().collect(),
                "aoeuidhtns-".chars().collect(),
                ";qjkxbmwvz".chars().collect(),
            ],
            "colemak" => vec![
                "qwfpgjluy;[]".chars().collect(),
                "arstdhneio'".chars().collect(),
                "zxcvbkm,./".chars().collect(),
            ],
            "colemakdh" => vec![
                "qwfpbjluy;[]".chars().collect(),
                "arstgmneiо'".chars().collect(),
                "zxcdvkh,./".chars().collect(),
            ],
            _ => vec![
                "qwertyuiop[]".chars().collect(),
                "asdfghjkl;'".chars().collect(),
                "zxcvbnm,./".chars().collect(),
            ],
        }
    };

    let in_rows = layout_rows(emu_in);
    let out_rows = layout_rows(emu_out);

    // Find position of c in emu_in
    for (ri, row) in in_rows.iter().enumerate() {
        for (ci, &key) in row.iter().enumerate() {
            if key == c {
                // Map to emu_out at same position
                if ri < out_rows.len() && ci < out_rows[ri].len() {
                    return out_rows[ri][ci];
                }
                return c;
            }
        }
    }

    c
}

