fn find_key_position(c: char, keys: &[[&str; 12]; 3]) -> Option<(usize, usize)> {
    for (ri, row) in keys.iter().enumerate() {
        for (ci, key) in row.iter().enumerate() {
            if key.len() == 1 && key.chars().next() == Some(c) {
                return Some((ri, ci));
            }
        }
    }
    None
}

fn get_ngram_list(args: &Args) -> Vec<String> {
    match args.n.as_str() {
        "2" => {
            let all = data::BIGRAMS;
            let top = args.top.min(all.len());
            all[..top].iter().map(|s| s.to_string()).collect()
        }
        "3" => {
            let all = data::TRIGRAMS;
            let top = args.top.min(all.len());
            all[..top].iter().map(|s| s.to_string()).collect()
        }
        "4" => {
            let all = data::TETRAGRAMS;
            let top = args.top.min(all.len());
            all[..top].iter().map(|s| s.to_string()).collect()
        }
        "w" => {
            let all = data::WORDS;
            let top = args.top.min(all.len());
            all[..top].iter().map(|s| s.to_string()).collect()
        }
        filename => {
            if let Ok(content) = std::fs::read_to_string(filename) {
                content.split(',')
                    .map(|s| s.trim().to_string())
                    .filter(|s| !s.is_empty())
                    .collect()
            } else {
                let all = data::BIGRAMS;
                let top = args.top.min(all.len());
                all[..top].iter().map(|s| s.to_string()).collect()
            }
        }
    }
}

fn generate_lesson(ngram_list: &[String], combi: usize, rep: usize) -> Vec<String> {
    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash, Hasher};
    use std::time::SystemTime;

    // Simple random using system time
    let now = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default()
        .subsec_nanos();

    let combi = combi.min(ngram_list.len().max(1));

    // Pick combi ngrams randomly with replacement
    let mut selected = Vec::new();
    let mut seed = now as u64;
    for _ in 0..combi {
        let idx = (seed as usize) % ngram_list.len();
        selected.push(ngram_list[idx].clone());
        // Simple LCG
        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
    }

    // Interleave: rep times each
    let mut lesson = Vec::new();
    for _ in 0..rep {
        for ng in &selected {
            lesson.push(ng.clone());
        }
    }
    lesson
}

struct AppState {
    lesson_num: u32,
    lesson: Vec<String>,
    current_ngram_idx: usize,
    current_char_idx: usize,
    typed_display: String,
    ngram_had_error: bool,
    ngram_errors: Vec<bool>,
    ngram_completed: Vec<bool>,
    lesson_start: Option<Instant>,
    lessons_passed: u32,
    lessons_failed: u32,
    avg_wpm: u32,
    last_wpm: u32,
    avg_acc: u32,
    last_acc: u32,
    lesson_complete: bool,
    total_errors: u32,
    total_correct: u32,
    needs_space: bool,
}

impl AppState {
    fn new(lesson: Vec<String>) -> Self {
        let n = lesson.len();
        AppState {
            lesson_num: 1,
            lesson,
            current_ngram_idx: 0,
            current_char_idx: 0,
            typed_display: String::new(),
            ngram_had_error: false,
            ngram_errors: vec![false; n],
            ngram_completed: vec![false; n],
            lesson_start: None,
            lessons_passed: 0,
            lessons_failed: 0,
            avg_wpm: 0,
            last_wpm: 0,
            avg_acc: 0,
            last_acc: 0,
            lesson_complete: false,
            total_errors: 0,
            total_correct: 0,
            needs_space: false,
        }
    }

    fn next_lesson(&mut self, lesson: Vec<String>) {
        let n = lesson.len();
        self.lesson = lesson;
        self.current_ngram_idx = 0;
        self.current_char_idx = 0;
        self.typed_display = String::new();
        self.ngram_had_error = false;
        self.ngram_errors = vec![false; n];
        self.ngram_completed = vec![false; n];
        self.lesson_start = None;
        self.lesson_complete = false;
        self.total_errors = 0;
        self.total_correct = 0;
        self.needs_space = false;
    }

    fn handle_char(&mut self, c: char) {
        if self.lesson_complete {
            return;
        }

        if self.needs_space {
            if c == ' ' {
                self.typed_display.push(' ');
                self.needs_space = false;
            }
            return;
        }

        if self.current_ngram_idx >= self.lesson.len() {
            return;
        }

        // Start timer on first character
        if self.lesson_start.is_none() {
            self.lesson_start = Some(Instant::now());
        }

        let current_ngram = &self.lesson[self.current_ngram_idx];
        let expected_char = current_ngram.chars().nth(self.current_char_idx);

        if let Some(exp) = expected_char {
            if c == exp {
                self.total_correct += 1;
                self.typed_display.push(c);
                self.current_char_idx += 1;

                if self.current_char_idx >= current_ngram.len() {
                    self.ngram_completed[self.current_ngram_idx] = true;
                    self.ngram_errors[self.current_ngram_idx] = self.ngram_had_error;
                    self.ngram_had_error = false;
                    self.current_ngram_idx += 1;
                    self.current_char_idx = 0;

                    if self.current_ngram_idx >= self.lesson.len() {
                        self.complete_lesson();
                    } else {
                        self.needs_space = true;
                    }
                }
            } else {
                self.total_errors += 1;
                self.ngram_had_error = true;
                self.typed_display.push(c);
            }
        }
    }

    fn complete_lesson(&mut self) {
        self.lesson_complete = true;

        if let Some(start) = self.lesson_start {
            let elapsed = start.elapsed();
            let seconds = elapsed.as_secs_f64();
            if seconds > 0.0 {
                let chars_typed: u32 = self.lesson.iter().map(|s| s.len() as u32).sum();
                let words = chars_typed as f64 / 5.0;
                let wpm = (words / (seconds / 60.0)) as u32;
                self.last_wpm = wpm;

                let total_lessons_done = self.lessons_passed + self.lessons_failed;
                if total_lessons_done == 0 {
                    self.avg_wpm = wpm;
                } else {
                    self.avg_wpm = ((self.avg_wpm as u64 * total_lessons_done as u64 
                                    + wpm as u64) / (total_lessons_done + 1) as u64) as u32;
                }
            }
        }

        let total_keystrokes = self.total_correct + self.total_errors;
        let acc = if total_keystrokes > 0 {
            (self.total_correct as f64 / total_keystrokes as f64 * 100.0) as u32
        } else {
            100
        };
        self.last_acc = acc;

        let total_lessons_done = self.lessons_passed + self.lessons_failed;
        if total_lessons_done == 0 {
            self.avg_acc = acc;
        } else {
            self.avg_acc = ((self.avg_acc as u64 * total_lessons_done as u64 
                             + acc as u64) / (total_lessons_done + 1) as u64) as u32;
        }
    }
}

// ANSI escape code helpers
const RESET: &str = "\x1b[0m";
const BOLD: &str = "\x1b[1m";
const ITALIC: &str = "\x1b[3m";
const GREEN: &str = "\x1b[38;5;2m";
const RED: &str = "\x1b[38;5;1m";
const BLUE: &str = "\x1b[38;5;4m";
const GRAY: &str = "\x1b[38;5;7m";
const YELLOW: &str = "\x1b[38;5;3m";
const WHITE: &str = "\x1b[38;5;15m";
const DIM_GRAY: &str = "\x1b[38;5;7m";

fn clear_screen(out: &mut impl Write) {
    write!(out, "\x1b[2J\x1b[H").ok();
}

fn goto(out: &mut impl Write, row: u16, col: u16) {
    write!(out, "\x1b[{};{}H", row + 1, col + 1).ok();
}

fn write_str(out: &mut impl Write, s: &str) {
    write!(out, "{}", s).ok();
}

fn get_terminal_size() -> (u16, u16) {
    term::get_terminal_size().unwrap_or((80, 24))
}

fn render(out: &mut impl Write, state: &AppState, args: &Args) {
    let (cols, rows) = get_terminal_size();

    // Check minimum size
    if cols < 80 || rows < 13 {
        clear_screen(out);
        goto(out, 1, 0);
        writeln!(out, "  Please resize your terminal to at least 80x13.").ok();
        writeln!(out, "             <esc> or <ctrl-c> to quit").ok();
        return;
    }

    // Clear and hide cursor
    write!(out, "\x1b[?25l").ok(); // hide cursor
    clear_screen(out);

    let width = cols;
    let inner_width = width - 2; // subtract border chars

    // Draw outer border box
    // Top border: ╭──...── Quit <esc> ╮
    goto(out, 0, 0);
    write!(out, "╭").ok();
    // Fill with dashes up to the title
    let quit_text = " Quit <esc> ";
    let dashes_count = inner_width as usize - quit_text.len();
    write!(out, "{}", "─".repeat(dashes_count)).ok();
    write!(out, "{}{}{}{}", BOLD, BLUE, quit_text, RESET).ok();
    write!(out, "╮").ok();

    // Title line: │  ngrrram!   by winterveil  │
    goto(out, 1, 0);
    write!(out, "│").ok();
    let title_ngrrram = "ngrrram!";
    let title_by = "   by winterveil";
    let title = format!("{}{}{}{}{}", BOLD, title_ngrrram, RESET, ITALIC, GRAY);
    // Center the title
    let visible_title_len = title_ngrrram.len() + title_by.len();
    let padding = (inner_width as usize).saturating_sub(visible_title_len) / 2;
    write!(out, "{}", " ".repeat(padding)).ok();
    write!(out, "{}{}{}", BOLD, title_ngrrram, RESET).ok();
    write!(out, "{}{}{}{}", ITALIC, GRAY, title_by, RESET).ok();
    let right_pad = inner_width as usize - padding - visible_title_len;
    write!(out, "{}", " ".repeat(right_pad)).ok();
    write!(out, "│").ok();

    // Separator
    goto(out, 2, 0);
    write!(out, "│{}│", "─".repeat(inner_width as usize)).ok();

    // Header: Lesson #N  ✔: 0, ✘: 0
    goto(out, 3, 0);
    write!(out, "│").ok();
    let left_header = format!("    Lesson #{}", state.lesson_num);
    let check_str = format!("✔: {}", state.lessons_passed);
    let x_str = format!("✘: {}", state.lessons_failed);
    let right_header = format!("{}, {}    ", check_str, x_str);
    let right_visible_len = check_str.len() + 2 + x_str.len() + 4; // ", " + "    "
    let mid_spaces = inner_width as usize - left_header.len() - right_visible_len;
    write!(out, "{}", left_header).ok();
    write!(out, "{}", " ".repeat(mid_spaces)).ok();
    write!(out, "{}{}{}", GREEN, check_str, RESET).ok();
    write!(out, ", ").ok();
    write!(out, "{}{}{}", RED, x_str, RESET).ok();
    write!(out, "    │").ok();

    // Separator
    goto(out, 4, 0);
    write!(out, "│{}│", "─".repeat(inner_width as usize)).ok();

    // Empty line
    goto(out, 5, 0);
    write!(out, "│{}│", " ".repeat(inner_width as usize)).ok();

    // Lesson text line (centered)
    goto(out, 6, 0);
    write!(out, "│").ok();

    // Build lesson text
    let mut lesson_text = String::new();
    let mut lesson_colored = String::new();

    for (i, ngram) in state.lesson.iter().enumerate() {
        if i > 0 {
            if state.ngram_completed[i-1] {
                lesson_text.push('•');
                lesson_colored.push_str(&format!("{}{}•{}", BOLD, RED, RESET));
            } else {
                lesson_text.push(' ');
                lesson_colored.push(' ');
            }
        }

        if state.ngram_completed[i] {
            let color = if state.ngram_errors[i] { RED } else { GREEN };
            lesson_colored.push_str(&format!("{}{}{}{}", BOLD, color, ngram, RESET));
            lesson_text.push_str(ngram);
        } else {
            lesson_colored.push_str(&format!("{}{}{}", BOLD, ngram, RESET));
            lesson_text.push_str(ngram);
        }
    }

    if state.lesson_complete {
        lesson_colored.push_str(&format!("{}{}•{}", BOLD, RED, RESET));
        lesson_text.push('•');
    }

    // Count visible length (without escape codes)
    let visible_len = lesson_text.chars().count();
    let text_padding = (inner_width as usize).saturating_sub(visible_len) / 2;
    let right_pad = inner_width as usize - text_padding - visible_len;

    write!(out, "{}", " ".repeat(text_padding)).ok();
    write!(out, "{}", lesson_colored).ok();
    write!(out, "{}", " ".repeat(right_pad)).ok();
    write!(out, "│").ok();

    // Typed text line (centered)
    goto(out, 7, 0);
    write!(out, "│").ok();

    let typed_text = &state.typed_display;
    let typed_visible = typed_text.chars().count();
    let typed_padding = (inner_width as usize).saturating_sub(typed_visible) / 2;
    let typed_right_pad = inner_width as usize - typed_padding - typed_visible;

    write!(out, "{}", " ".repeat(typed_padding)).ok();
    if !typed_text.is_empty() {
        write!(out, "{}{}{}{}", ITALIC, GRAY, typed_text, RESET).ok();
    }
    write!(out, "{}", " ".repeat(typed_right_pad)).ok();
    write!(out, "│").ok();

    let mut next_row = 8u16;

    // Keyboard display
    if !args.nokb {
        // Empty line before keyboard
        goto(out, next_row, 0);
        write!(out, "│{}│", " ".repeat(inner_width as usize)).ok();
        next_row += 1;

        let kb_layout_name = if !args.emu_out.is_empty() {
            args.emu_out.as_str()
        } else {
            "qwerty"
        };
        let kb_keys = get_keyboard_display_keys(kb_layout_name);

        // Determine next char for highlighting
        let next_char = if !state.lesson_complete && state.current_ngram_idx < state.lesson.len() {
            if state.needs_space {
                None // don't highlight for space
            } else {
                state.lesson[state.current_ngram_idx]
                    .chars()
                    .nth(state.current_char_idx)
            }
        } else {
            None
        };

        let highlight_pos = next_char.and_then(|c| find_key_position(c, &kb_keys));

        if args.show_ortho {
            render_kb_ortho(out, next_row, width, &kb_keys, highlight_pos);
            next_row += 5;
        } else {
            render_kb_staggered(out, next_row, width, &kb_keys, highlight_pos);
            next_row += 7;
        }
    } else {
        // Two empty lines (matching with-keyboard height more or less)
        goto(out, next_row, 0);
        write!(out, "│{}│", " ".repeat(inner_width as usize)).ok();
        next_row += 1;
        goto(out, next_row, 0);
        write!(out, "│{}│", " ".repeat(inner_width as usize)).ok();
        next_row += 1;
    }

    // Separator before stats
    goto(out, next_row, 0);
    write!(out, "│{}│", "─".repeat(inner_width as usize)).ok();
    next_row += 1;

    // WPM stats line
    goto(out, next_row, 0);
    write!(out, "│").ok();
    render_stats_wpm(out, state, args, inner_width as usize);
    write!(out, "│").ok();
    next_row += 1;

    // Accuracy stats line
    goto(out, next_row, 0);
    write!(out, "│").ok();

    // Cat in bottom right of stats area
    if args.cat {
        render_stats_acc_with_cat(out, state, args, inner_width as usize, next_row);
    } else {
        render_stats_acc(out, state, args, inner_width as usize);
        write!(out, "│").ok();
    }
    next_row += 1;

    // Bottom border
    goto(out, next_row, 0);
    write!(out, "╰{}╯", "─".repeat(inner_width as usize)).ok();

    out.flush().ok();
}

fn render_stats_wpm(out: &mut impl Write, state: &AppState, args: &Args, width: usize) {
    let need_part = format!("  need >= {:3}WPM,   avg.", args.wpm);
    let avg_part = format!(" {:3}WPM", state.avg_wpm);
    let comma_part = format!(",   last");
    let last_part = format!(" {:3}WPM", state.last_wpm);

    let total_len = need_part.len() + avg_part.len() + comma_part.len() + last_part.len();
    let right_pad = " ".repeat(width.saturating_sub(total_len));

    write!(out, "{}{}", DIM_GRAY, need_part).ok();
    write!(out, "{}{}{}", RESET, WHITE, avg_part).ok();
    write!(out, "{}{}", DIM_GRAY, comma_part).ok();
    write!(out, "{}{}{}", RESET, WHITE, last_part).ok();
    write!(out, "{}{}", RESET, right_pad).ok();
}

fn render_stats_acc(out: &mut impl Write, state: &AppState, args: &Args, width: usize) {
    let need_part = format!("  need >= {:3}% Acc, avg.", args.acc);
    let avg_part = format!(" {:3}% Acc", state.avg_acc);
    let comma_part = format!(", last");
    let last_part = format!(" {:3}% Acc", state.last_acc);

    let total_len = need_part.len() + avg_part.len() + comma_part.len() + last_part.len();
    let right_pad = " ".repeat(width.saturating_sub(total_len));

    write!(out, "{}{}", DIM_GRAY, need_part).ok();
    write!(out, "{}{}{}", RESET, WHITE, avg_part).ok();
    write!(out, "{}{}", DIM_GRAY, comma_part).ok();
    write!(out, "{}{}{}", RESET, WHITE, last_part).ok();
    write!(out, "{}{}", RESET, right_pad).ok();
}

fn render_stats_acc_with_cat(out: &mut impl Write, state: &AppState, args: &Args, width: usize, row: u16) {
    // The cat takes up space on the right
    // Cat lines:
    // /\_/\
