fn render_kb_staggered(
    out: &mut impl Write,
    start_row: u16,
    width: u16,
    keys: &[[&str; 12]; 3],
    highlight: Option<(usize, usize)>,
) {
    let inner_width = width as usize - 2;
    let indent = 13usize;

    // Row 0 keys (non-empty)
    let r0: Vec<&str> = keys[0].iter().filter(|&&k| !k.is_empty()).copied().collect();
    let r1: Vec<&str> = keys[1].iter().filter(|&&k| !k.is_empty()).copied().collect();
    let r2: Vec<&str> = keys[2].iter().filter(|&&k| !k.is_empty()).copied().collect();

    let n0 = r0.len();
    let n1 = r1.len();
    let n2 = r2.len();

    // Build lines
    // Top of row 0
    let row0_top = format!("{}┌{}",
        " ".repeat(indent),
        (0..n0).map(|i| {
            let mut s = String::from("───");
            if i < n0 - 1 { s.push('┬'); }
            s
        }).collect::<String>() + "┐"
    );

    // Content of row 0
    // Bottom of row 0 / top of row 1 (staggered)
    let row0_bot = format!("{}└{}",
        " ".repeat(indent),
        (0..n0).map(|i| {
            let mut s = String::from("┬──");
            if i < n0 - 1 { s.push('┴'); }
            s
        }).collect::<String>() + "┘"
    );

    // Content of row 1
    // Bottom of row 1 / top of row 2
    let row1_bot = format!("{} └{}",
        " ".repeat(indent),
        (0..n1).map(|i| {
            let mut s = String::from("┬──");
            if i < n1 - 1 { s.push('┴'); }
            s
        }).collect::<String>() + "┘"
    );

    // Content of row 2
    // Bottom of row 2
    let row2_bot = format!("{}  └{}",
        " ".repeat(indent),
        (0..n2).map(|i| {
            let mut s = String::from("───");
            if i < n2 - 1 { s.push('┴'); }
            s
        }).collect::<String>() + "┘"
    );

    let right_pad = |s: &str| {
        let len = s.chars().count();
        let pad = inner_width.saturating_sub(len);
        format!("{}{}", s, " ".repeat(pad))
    };

    // Row 0 top
    goto(out, start_row, 0);
    write!(out, "│").ok();
    write!(out, "{}{}{}", GRAY, right_pad(&row0_top), RESET).ok();
    write!(out, "│").ok();

    // Row 0 content
    goto(out, start_row + 1, 0);
    write!(out, "│").ok();
    write!(out, "{}{}", GRAY, " ".repeat(indent)).ok();
    write!(out, "│").ok();
    for (ci, key) in r0.iter().enumerate() {
        if highlight == Some((0, ci)) {
            write!(out, " {}{}{} ", YELLOW, key, GRAY).ok();
        } else {
            write!(out, " {} ", key).ok();
        }
        write!(out, "│").ok();
    }
    let row0_content_len = indent + 1 + n0 * 4;
    write!(out, "{}", " ".repeat(inner_width.saturating_sub(row0_content_len))).ok();
    write!(out, "{}", RESET).ok();
    write!(out, "│").ok();

    // Row 0 bottom / Row 1 top
    goto(out, start_row + 2, 0);
    write!(out, "│").ok();
    write!(out, "{}{}{}", GRAY, right_pad(&row0_bot), RESET).ok();
    write!(out, "│").ok();

    // Row 1 content
    goto(out, start_row + 3, 0);
    write!(out, "│").ok();
    write!(out, "{}{}", GRAY, " ".repeat(indent + 1)).ok();
    write!(out, "│").ok();
    for (ci, key) in r1.iter().enumerate() {
        if highlight == Some((1, ci)) {
            write!(out, " {}{}{} ", YELLOW, key, GRAY).ok();
        } else {
            write!(out, " {} ", key).ok();
        }
        write!(out, "│").ok();
    }
    let row1_content_len = indent + 1 + 1 + n1 * 4;
    write!(out, "{}", " ".repeat(inner_width.saturating_sub(row1_content_len))).ok();
    write!(out, "{}", RESET).ok();
    write!(out, "│").ok();

    // Row 1 bottom / Row 2 top
    goto(out, start_row + 4, 0);
    write!(out, "│").ok();
    write!(out, "{}{}{}", GRAY, right_pad(&row1_bot), RESET).ok();
    write!(out, "│").ok();

    // Row 2 content
    goto(out, start_row + 5, 0);
    write!(out, "│").ok();
    write!(out, "{}{}", GRAY, " ".repeat(indent + 2)).ok();
    write!(out, "│").ok();
    for (ci, key) in r2.iter().enumerate() {
        if highlight == Some((2, ci)) {
            write!(out, " {}{}{} ", YELLOW, key, GRAY).ok();
        } else {
            write!(out, " {} ", key).ok();
        }
        write!(out, "│").ok();
    }
    let row2_content_len = indent + 2 + 1 + n2 * 4;
    write!(out, "{}", " ".repeat(inner_width.saturating_sub(row2_content_len))).ok();
    write!(out, "{}", RESET).ok();
    write!(out, "│").ok();

    // Row 2 bottom
    goto(out, start_row + 6, 0);
    write!(out, "│").ok();
    write!(out, "{}{}{}", GRAY, right_pad(&row2_bot), RESET).ok();
    write!(out, "│").ok();
}

fn render_kb_ortho(
    out: &mut impl Write,
    start_row: u16,
    width: u16,
    keys: &[[&str; 12]; 3],
    highlight: Option<(usize, usize)>,
) {
    let inner_width = width as usize - 2;
    let indent = 13usize;
    let n = 12usize;

    let build_top = || format!("{}┌{}", " ".repeat(indent),
        (0..n).map(|i| { let s = String::from("───"); if i < n-1 { s + "┬" } else { s + "┐" } }).collect::<String>());
    let build_mid = || format!("{}├{}", " ".repeat(indent),
        (0..n).map(|i| { let s = String::from("───"); if i < n-1 { s + "┼" } else { s + "┤" } }).collect::<String>());
    let build_bot = || format!("{}└{}", " ".repeat(indent),
        (0..n).map(|i| { let s = String::from("───"); if i < n-1 { s + "┴" } else { s + "┘" } }).collect::<String>());

    let right_pad = |s: &str| {
        let len = s.chars().count();
        let pad = inner_width.saturating_sub(len);
        format!("{}{}", s, " ".repeat(pad))
    };

    goto(out, start_row, 0);
    write!(out, "│{}{}{}│", GRAY, right_pad(&build_top()), RESET).ok();

    for row_idx in 0..3usize {
        goto(out, start_row + 1 + row_idx as u16 * 2, 0);
        write!(out, "│").ok();
        write!(out, "{}{}", GRAY, " ".repeat(indent)).ok();
        write!(out, "│").ok();
        for ci in 0..n {
            let key = keys[row_idx][ci];
            let display = if key.is_empty() { "△" } else { key };
            if key.is_empty() {
                write!(out, " {} │", display).ok();
            } else if highlight == Some((row_idx, ci)) {
                write!(out, " {}{}{} {}│", YELLOW, display, GRAY, "").ok();
            } else {
                write!(out, " {} │", display).ok();
            }
        }
        let content_len = indent + 1 + n * 4;
        write!(out, "{}", " ".repeat(inner_width.saturating_sub(content_len))).ok();
        write!(out, "{}│", RESET).ok();

        if row_idx < 2 {
            goto(out, start_row + 2 + row_idx as u16 * 2, 0);
            write!(out, "│{}{}{}│", GRAY, right_pad(&build_mid()), RESET).ok();
        }
    }

    goto(out, start_row + 6, 0);
    write!(out, "│{}{}{}│", GRAY, right_pad(&build_bot()), RESET).ok();
}

fn main() {
    let args = match Args::parse() {
        Ok(a) => a,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };

    let ngram_list = get_ngram_list(&args);
    let lesson = generate_lesson(&ngram_list, args.combi, args.rep);
    let mut state = AppState::new(lesson);

    // Enter raw terminal mode
    let mut raw = match term::RawTerminal::new() {
        Ok(r) => r,
        Err(e) => {
            eprintln!("Failed to enter raw mode: {}", e);
            std::process::exit(1);
        }
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    // Initial render
    render(&mut out, &state, &args);

    let mut running = true;

    while running {
        // Read input
        let mut buf = [0u8; 4];
        match raw.read_char() {
            Some(c) => {
                match c {
                    '\x1b' => {
                        // ESC key - check if it's a sequence or just ESC
                        running = false;
                    }
                    '\x03' => {
                        // Ctrl+C
                        running = false;
                    }
                    '\x7f' | '\x08' => {
                        // Backspace/Delete - ignore
                    }
                    ' ' => {
                        if state.lesson_complete {
                            // Advance to next lesson
                            let passed = state.last_wpm >= args.wpm && state.last_acc >= args.acc;
                            if passed {
                                state.lessons_passed += 1;
                            } else {
                                state.lessons_failed += 1;
                            }
                            state.lesson_num += 1;
                            let lesson = generate_lesson(&ngram_list, args.combi, args.rep);
                            state.next_lesson(lesson);
                            // Process the space as first char of next lesson (it's just a separator)
                        } else {
                            let mapped = map_char_for_emulation(' ', &args.emu_in, &args.emu_out);
                            state.handle_char(mapped);
                        }
                    }
                    _ if c.is_ascii_graphic() || c == ' ' => {
                        if state.lesson_complete {
                            // Any key advances to next lesson
                            let passed = state.last_wpm >= args.wpm && state.last_acc >= args.acc;
                            if passed {
                                state.lessons_passed += 1;
                            } else {
                                state.lessons_failed += 1;
                            }
                            state.lesson_num += 1;
                            let lesson = generate_lesson(&ngram_list, args.combi, args.rep);
                            state.next_lesson(lesson);
                            // Process this char as first char
                            let mapped = map_char_for_emulation(c, &args.emu_in, &args.emu_out);
                            state.handle_char(mapped);
                        } else {
                            let mapped = map_char_for_emulation(c, &args.emu_in, &args.emu_out);
                            state.handle_char(mapped);
                        }
                    }
                    _ => {}
                }
            }
            None => {
                // Timeout or error, just re-render
            }
        }

        if running {
            render(&mut out, &state, &args);
        }
    }

    // Cleanup
    drop(raw);
    write!(out, "\x1b[?25h").ok(); // show cursor
    out.flush().ok();
}
