    #[derive(Clone)]
    pub struct Termios {
        pub c_iflag: u32,
        pub c_oflag: u32,
        pub c_cflag: u32,
        pub c_lflag: u32,
        pub c_line: u8,
        pub c_cc: [u8; 32],
        pub c_ispeed: u32,
        pub c_ospeed: u32,
    }

    #[repr(C)]
    pub struct Winsize {
        pub ws_row: u16,
        pub ws_col: u16,
        pub ws_xpixel: u16,
        pub ws_ypixel: u16,
    }

    pub fn get_termios(fd: RawFd) -> Option<Termios> {
        let mut t = Termios {
            c_iflag: 0, c_oflag: 0, c_cflag: 0, c_lflag: 0,
            c_line: 0, c_cc: [0; 32], c_ispeed: 0, c_ospeed: 0,
        };
        unsafe {
            if tcgetattr(fd, &mut t) == 0 {
                Some(t)
            } else {
                None
            }
        }
    }

    pub fn set_termios(fd: RawFd, t: &Termios) -> bool {
        unsafe { tcsetattr(fd, TCSANOW, t) == 0 }
    }

    pub fn make_raw(t: &mut Termios) {
        // cfmakeraw equivalent
        t.c_iflag &= !(0o0000001 | 0o0000002 | 0o0000010 | 0o0000200 | 0o0001000 | 
                        0o0002000 | 0o0004000 | 0o0010000 | 0o0020000);
        t.c_oflag &= !0o0000001;
        t.c_cflag &= !(0o0000060 | 0o0000100 | 0o0300000);
        t.c_cflag |= 0o0000060 | 0o0000400;
        t.c_lflag &= !(0o0000010 | 0o0000100 | 0o0000200 | 0o0000400 | 0o0001000 | 0o0010000 | 0o0040000);
        t.c_cc[6] = 1;  // VMIN
        t.c_cc[5] = 0;  // VTIME
    }

    pub fn get_winsize(fd: RawFd) -> Option<(u16, u16)> {
        let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
        unsafe {
            if ioctl(fd, TIOCGWINSZ, &mut ws) == 0 {
                Some((ws.ws_col, ws.ws_row))
            } else {
                None
            }
        }
    }
