        t.c_cflag &= !(0o0000060 | 0o0000100 | 0o0300000);
        t.c_cflag |= 0o0000060 | 0o0000400;
        t.c_lflag &= !(0o0000010 | 0o0000100 | 0o0000200 | 0o0000400 | 0o0001000 | 0o0010000 | 0o0040000);
        t.c_cc[6] = 1;  // VMIN
        t.c_cc[5] = 0;  // VTIME
    }

    pub fn get_winsize(fd: RawFd) -> Option<(u16, u16)> {
        let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
        unsafe {
            if ioctl(fd, TIOCGWINSZ, &mut ws) == 0 {
                Some((ws.ws_col, ws.ws_row))
            } else {
                None
            }
        }
    }
}

pub struct RawTerminal {
    fd: i32,
    orig: sys::Termios,
}

impl RawTerminal {
    pub fn new() -> io::Result<Self> {
        use std::os::unix::io::AsRawFd;
        let fd = io::stdin().as_raw_fd();

        let orig = sys::get_termios(fd)
            .ok_or_else(|| io::Error::new(io::ErrorKind::Other, "tcgetattr failed"))?;

        let mut raw = orig.clone();
        sys::make_raw(&mut raw);

        if !sys::set_termios(fd, &raw) {
            return Err(io::Error::new(io::ErrorKind::Other, "tcsetattr failed"));
        }

        Ok(RawTerminal { fd, orig })
    }

    pub fn read_char(&mut self) -> Option<char> {
        use std::os::unix::io::FromRawFd;

        // Read a single byte
        let mut buf = [0u8; 1];
        unsafe {
            let n = libc_read(self.fd, buf.as_mut_ptr() as *mut _, 1);
            if n <= 0 {
                return None;
            }
        }

        let b = buf[0];

        // Handle multi-byte sequences
        if b < 0x80 {
            Some(b as char)
        } else if b & 0xE0 == 0xC0 {
            // 2-byte UTF-8
            let mut buf2 = [0u8; 1];
            unsafe { libc_read(self.fd, buf2.as_mut_ptr() as *mut _, 1); }
            let codepoint = ((b & 0x1F) as u32) << 6 | (buf2[0] & 0x3F) as u32;
            char::from_u32(codepoint)
        } else if b & 0xF0 == 0xE0 {
            // 3-byte UTF-8
            let mut buf2 = [0u8; 2];
            unsafe { libc_read(self.fd, buf2.as_mut_ptr() as *mut _, 2); }
            let codepoint = ((b & 0x0F) as u32) << 12 
                | ((buf2[0] & 0x3F) as u32) << 6 
                | (buf2[1] & 0x3F) as u32;
            char::from_u32(codepoint)
        } else {
            None
        }
    }
}

extern "C" {
    fn read(fd: i32, buf: *mut libc::c_void, count: libc::size_t) -> libc::ssize_t;
}

fn libc_read(fd: i32, buf: *mut u8, count: usize) -> isize {
    unsafe { read(fd, buf as *mut _, count) as isize }
}

mod libc {
    pub type c_void = std::ffi::c_void;
    pub type size_t = usize;
    pub type ssize_t = isize;
}

impl Drop for RawTerminal {
    fn drop(&mut self) {
        sys::set_termios(self.fd, &self.orig);
    }
}

pub fn get_terminal_size() -> Option<(u16, u16)> {
    use std::os::unix::io::AsRawFd;
    let fd = io::stdout().as_raw_fd();
    sys::get_winsize(fd)
}
