use args::Args;

// ─────────────────────────────────────────
// Keyboard layout definitions
// ─────────────────────────────────────────

fn layout_rows(name: &str) -> [&'static [&'static str]; 3] {
    match name {
        "qwerty" => [
            &["q","w","e","r","t","y","u","i","o","p","[","]"][..],
            &["a","s","d","f","g","h","j","k","l",";","'"][..],
            &["z","x","c","v","b","n","m",",",".","/"][..],
        ],
        "qwertz" => [
            &["q","w","e","r","t","z","u","i","o","p","[","]"][..],
            &["a","s","d","f","g","h","j","k","l",";","'"][..],
            &["y","x","c","v","b","n","m",",",".","/"][..],
        ],
        "azerty" => [
            &["a","z","e","r","t","y","u","i","o","p","[","]"][..],
            &["q","s","d","f","g","h","j","k","l",";","'"][..],
            &["w","x","c","v","b","n","m",",",".","/"][..],
        ],
        "dvorak" => [
            &["'",",",".","p","y","f","g","c","r","l","/","="][..],
            &["a","o","e","u","i","d","h","t","n","s","-"][..],
            &[";","q","j","k","x","b","m","w","v","z"][..],
        ],
        "colemak" => [
            &["q","w","f","p","g","j","l","u","y",";","[","]"][..],
            &["a","r","s","t","d","h","n","e","i","o","'"][..],
            &["z","x","c","v","b","k","m",",",".","/"][..],
        ],
        "colemakdh" => [
            &["q","w","f","p","b","j","l","u","y",";","[","]"][..],
            &["a","r","s","t","g","m","n","e","i","o","'"][..],
            &["z","x","c","d","v","k","h",",",".","/"][..],
        ],
        _ => [  // default qwerty
            &["q","w","e","r","t","y","u","i","o","p","[","]"][..],
            &["a","s","d","f","g","h","j","k","l",";","'"][..],
            &["z","x","c","v","b","n","m",",",".","/"][..],
        ],
    }
}

fn map_char_emulation(c: char, emu_in: &str, emu_out: &str) -> char {
    if emu_in.is_empty() || emu_out.is_empty() {
        return c;
    }
    let in_rows = layout_rows(emu_in);
    let out_rows = layout_rows(emu_out);
    for (ri, row) in in_rows.iter().enumerate() {
        for (ci, key) in row.iter().enumerate() {
            if key.len() == 1 && key.chars().next() == Some(c) {
                if ri < out_rows.len() && ci < out_rows[ri].len() {
                    let out_key = out_rows[ri][ci];
                    if out_key.len() == 1 {
                        return out_key.chars().next().unwrap();
                    }
                }
                return c;
            }
        }
    }
    c
}

fn find_key_pos(c: char, rows: [&[&str]; 3]) -> Option<(usize, usize)> {
    for (ri, row) in rows.iter().enumerate() {
        for (ci, key) in row.iter().enumerate() {
            if key.len() == 1 && key.chars().next() == Some(c) {
                return Some((ri, ci));
            }
        }
    }
    None
}

