        ],
    }
}

fn map_char_emulation(c: char, emu_in: &str, emu_out: &str) -> char {
    if emu_in.is_empty() || emu_out.is_empty() {
        return c;
    }
    let in_rows = layout_rows(emu_in);
    let out_rows = layout_rows(emu_out);
    for (ri, row) in in_rows.iter().enumerate() {
        for (ci, key) in row.iter().enumerate() {
            if key.len() == 1 && key.chars().next() == Some(c) {
                if ri < out_rows.len() && ci < out_rows[ri].len() {
                    let out_key = out_rows[ri][ci];
                    if out_key.len() == 1 {
                        return out_key.chars().next().unwrap();
                    }
                }
                return c;
            }
        }
    }
    c
}

fn find_key_pos(c: char, rows: [&[&str]; 3]) -> Option<(usize, usize)> {
    for (ri, row) in rows.iter().enumerate() {
        for (ci, key) in row.iter().enumerate() {
            if key.len() == 1 && key.chars().next() == Some(c) {
                return Some((ri, ci));
            }
        }
    }
    None
}

