// Simple PRNG (LCG)
fn next_seed(seed: u64) -> u64 {
    seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407)
}

fn generate_lesson(ngram_list: &[String], combi: usize, rep: usize) -> Vec<String> {
    use std::time::SystemTime;
    let seed_base = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default()
        .subsec_nanos() as u64;

    let combi = combi.min(ngram_list.len().max(1));
    let mut seed = seed_base;

    let mut selected = Vec::new();
    for _ in 0..combi {
        seed = next_seed(seed);
        let idx = (seed >> 32) as usize % ngram_list.len();
        selected.push(ngram_list[idx].clone());
    }

    // interleaved: ngram0 ngram1 ngram0 ngram1 (rep times each)
    let mut lesson = Vec::new();
    for _ in 0..rep {
        for ng in &selected {
            lesson.push(ng.clone());
        }
    }
    lesson
}

// ─────────────────────────────────────────
// App State
// ─────────────────────────────────────────

struct AppState {
    lesson_num: u32,
    lesson: Vec<String>,
    cur_ngram: usize,
    cur_char: usize,
    typed_buf: String,    // what user has typed so far (shown below lesson text)
    ngram_error: bool,    // current ngram has had an error
    ngram_errors: Vec<bool>,    // per-ngram error flag
    ngram_done: Vec<bool>,      // per-ngram completion flag
    start_time: Option<Instant>,
    passed: u32,
    failed: u32,
    avg_wpm: u32,
    last_wpm: u32,
    avg_acc: u32,
    last_acc: u32,
    complete: bool,
    need_space: bool,  // after completing ngram, need space before next
    total_correct: u32,
    total_errors: u32,
}

impl AppState {
    fn new(lesson: Vec<String>) -> Self {
        let n = lesson.len();
        AppState {
            lesson_num: 1,
            lesson,
            cur_ngram: 0,
            cur_char: 0,
            typed_buf: String::new(),
            ngram_error: false,
            ngram_errors: vec![false; n],
            ngram_done: vec![false; n],
            start_time: None,
            passed: 0,
            failed: 0,
            avg_wpm: 0,
            last_wpm: 0,
            avg_acc: 0,
            last_acc: 0,
            complete: false,
            need_space: false,
            total_correct: 0,
            total_errors: 0,
        }
    }

    fn reset_lesson(&mut self, lesson: Vec<String>) {
        let n = lesson.len();
        self.lesson = lesson;
        self.cur_ngram = 0;
        self.cur_char = 0;
        self.typed_buf = String::new();
        self.ngram_error = false;
        self.ngram_errors = vec![false; n];
        self.ngram_done = vec![false; n];
        self.start_time = None;
        self.complete = false;
        self.need_space = false;
        self.total_correct = 0;
        self.total_errors = 0;
    }

    fn handle_char(&mut self, c: char) {
        if self.complete {
            return;
        }

        if self.need_space {
            if c == ' ' {
                self.typed_buf.push(' ');
                self.need_space = false;
            }
            // Wrong key during space wait: ignore
            return;
        }

        if self.cur_ngram >= self.lesson.len() {
            return;
        }

        // Start timer
        if self.start_time.is_none() {
            self.start_time = Some(Instant::now());
        }

        let expected = self.lesson[self.cur_ngram].chars().nth(self.cur_char);
        if let Some(exp) = expected {
            if c == exp {
                self.total_correct += 1;
                self.typed_buf.push(c);
                self.cur_char += 1;

                if self.cur_char >= self.lesson[self.cur_ngram].len() {
                    // Ngram complete
                    self.ngram_done[self.cur_ngram] = true;
                    self.ngram_errors[self.cur_ngram] = self.ngram_error;
                    self.ngram_error = false;
                    self.cur_ngram += 1;
                    self.cur_char = 0;

                    if self.cur_ngram >= self.lesson.len() {
                        self.finish_lesson();
                    } else {
                        self.need_space = true;
                    }
                }
            } else {
                self.total_errors += 1;
                self.ngram_error = true;
                self.typed_buf.push(c);  // Show wrong char
            }
        }
    }

    fn finish_lesson(&mut self) {
        self.complete = true;

        if let Some(t) = self.start_time {
            let elapsed = t.elapsed().as_secs_f64();
            if elapsed > 0.0 {
                let chars: u32 = self.lesson.iter().map(|s| s.len() as u32).sum();
                let wpm = ((chars as f64 / 5.0) / (elapsed / 60.0)) as u32;
                self.last_wpm = wpm;
                let done = self.passed + self.failed;
                self.avg_wpm = if done == 0 {
                    wpm
                } else {
                    ((self.avg_wpm as u64 * done as u64 + wpm as u64) / (done as u64 + 1)) as u32
                };
            }
        }

        let total = self.total_correct + self.total_errors;
        let acc = if total > 0 {
            (self.total_correct as f64 / total as f64 * 100.0) as u32
        } else {
            100
        };
        self.last_acc = acc;
        let done = self.passed + self.failed;
        self.avg_acc = if done == 0 {
            acc
        } else {
            ((self.avg_acc as u64 * done as u64 + acc as u64) / (done as u64 + 1)) as u32
        };
    }
}

