const ESC: &str = "\x1b";
const RESET: &str = "\x1b[0m";
const BOLD: &str = "\x1b[1m";
const ITALIC: &str = "\x1b[3m";
const FG_GREEN: &str = "\x1b[38;5;2m";
const FG_RED: &str = "\x1b[38;5;1m";
const FG_BLUE: &str = "\x1b[38;5;4m";
const FG_GRAY: &str = "\x1b[38;5;7m";
const FG_YELLOW: &str = "\x1b[38;5;3m";
const FG_WHITE: &str = "\x1b[38;5;15m";

fn goto(out: &mut impl Write, row: u16, col: u16) {
    write!(out, "\x1b[{};{}H", row + 1, col + 1).ok();
}

// ─────────────────────────────────────────
// Rendering constants
// ─────────────────────────────────────────
const BOX_WIDTH: usize = 79;  // Total box width
const INNER_WIDTH: usize = 77; // Inner content width (BOX_WIDTH - 2 borders)

fn center_pad(s: &str, width: usize) -> (usize, usize) {
    let len = s.chars().count();
    let avail = width.saturating_sub(len);
    let left = avail / 2;
    let right = avail - left;
    (left, right)
}

fn render_line(out: &mut impl Write, row: u16, content: &str) {
    goto(out, row, 0);
    write!(out, "│{}│", content).ok();
}

fn render_separator(out: &mut impl Write, row: u16) {
    goto(out, row, 0);
    write!(out, "│{}│", "─".repeat(INNER_WIDTH)).ok();
}

fn render_blank(out: &mut impl Write, row: u16) {
    goto(out, row, 0);
    write!(out, "│{}│", " ".repeat(INNER_WIDTH)).ok();
}

// ─────────────────────────────────────────
// Main render function
// ─────────────────────────────────────────
fn render(out: &mut impl Write, state: &AppState, args: &Args) {
    let (cols, rows) = term::get_terminal_size().unwrap_or((80, 24));

    // Check minimum size
    if cols < 80 || rows < 13 {
        write!(out, "\x1b[2J\x1b[H").ok();
        goto(out, 1, 0);
        writeln!(out, "  Please resize your terminal to at least 80x13.").ok();
        writeln!(out, "             <esc> or <ctrl-c> to quit").ok();
        out.flush().ok();
        return;
    }

    write!(out, "\x1b[?25l").ok();  // hide cursor
    write!(out, "\x1b[2J\x1b[H").ok();  // clear

    // Row 0: Top border with "Quit <esc>" title
    goto(out, 0, 0);
    let quit = " Quit <esc> ";
    let dashes = INNER_WIDTH - quit.len();
    write!(out, "╭{}{}{}{}{}╮", 
        "─".repeat(dashes),
        BOLD, FG_BLUE, quit, RESET
    ).ok();

    // Row 1: Title "ngrrram!   by winterveil" centered in 77
    // From observation: 34 spaces left, 19 right  
    // But let me compute it properly using ratatui-like centering:
    // The visible content "ngrrram!   by winterveil" = 24 chars
    // Centering: left = (77-24)/2 = 26 (floor)
    // BUT original shows 34! There must be something different.
    // I'll match exactly what's observed.
    {
        goto(out, 1, 0);
        write!(out, "│").ok();
        // Exact centering as observed: 34 spaces + content + 19 spaces
        let title_visible = "ngrrram!   by winterveil";
        let left_pad = (INNER_WIDTH - title_visible.len()) / 2;
        let right_pad = INNER_WIDTH - title_visible.len() - left_pad;
        write!(out, "{}", " ".repeat(left_pad)).ok();
        write!(out, "{}{}ngrrram!{}", BOLD, "", RESET).ok();
        write!(out, "{}{}   by winterveil{}", ITALIC, FG_GRAY, RESET).ok();
        write!(out, "{}", " ".repeat(right_pad)).ok();
        write!(out, "│").ok();
    }

    // Row 2: Separator
    render_separator(out, 2);

    // Row 3: "Lesson #N    ✔:0, ✘:0"
    {
        goto(out, 3, 0);
        write!(out, "│").ok();
        let left = format!("    Lesson #{}", state.lesson_num);
        let check = format!("✔: {}", state.passed);
        let x = format!("✘: {}", state.failed);
        let right = format!("{}, {}", check, x);
        // right_pad after ✘: 4 spaces
        let right_with_pad = format!("{}    ", right);
        let spaces = INNER_WIDTH.saturating_sub(left.len() + right_with_pad.len());
        write!(out, "{}", left).ok();
        write!(out, "{}", " ".repeat(spaces)).ok();
        write!(out, "{}{}{}", FG_GREEN, check, RESET).ok();
        write!(out, ", ").ok();
        write!(out, "{}{}{}", FG_RED, x, RESET).ok();
        write!(out, "    │").ok();
    }

    // Row 4: Separator
    render_separator(out, 4);

    // Row 5: Blank
    render_blank(out, 5);

    // Row 6: Lesson text
    {
        goto(out, 6, 0);
        write!(out, "│").ok();

        // Build visible lesson string (for centering)
        let mut vis = String::new();
        for (i, ng) in state.lesson.iter().enumerate() {
            if i > 0 {
                if state.ngram_done[i-1] {
                    vis.push('•');
                } else {
                    vis.push(' ');
                }
            }
            vis.push_str(ng);
        }
        if state.complete {
            vis.push('•');
        }

        let vis_len = vis.chars().count();
        let left_pad = (INNER_WIDTH.saturating_sub(vis_len)) / 2;
        let right_pad = INNER_WIDTH.saturating_sub(vis_len) - left_pad;

        write!(out, "{}", " ".repeat(left_pad)).ok();

        // Render with colors
        for (i, ng) in state.lesson.iter().enumerate() {
            if i > 0 {
                if state.ngram_done[i-1] {
                    write!(out, "{}{}", BOLD, FG_RED).ok();
                    write!(out, "•").ok();
                    write!(out, "{}", RESET).ok();
                } else {
                    write!(out, " ").ok();
                }
            }
            if state.ngram_done[i] {
                let color = if state.ngram_errors[i] { FG_RED } else { FG_GREEN };
                write!(out, "{}{}{}{}", BOLD, color, ng, RESET).ok();
            } else {
                write!(out, "{}{}{}", BOLD, ng, RESET).ok();
            }
        }
        if state.complete {
            write!(out, "{}{}", BOLD, FG_RED).ok();
            write!(out, "•").ok();
            write!(out, "{}", RESET).ok();
        }

        write!(out, "{}", " ".repeat(right_pad)).ok();
        write!(out, "│").ok();
    }

    // Row 7: Typed buffer (shown in italic gray, centered to match)
    {
        goto(out, 7, 0);
        write!(out, "│").ok();

        let typed = &state.typed_buf;
        let typed_len = typed.chars().count();

        // Center same as lesson text (use same vis_len for alignment)
        let mut vis = String::new();
        for (i, ng) in state.lesson.iter().enumerate() {
            if i > 0 {
                if state.ngram_done[i-1] { vis.push('•'); } else { vis.push(' '); }
            }
            vis.push_str(ng);
        }
        if state.complete { vis.push('•'); }
        let vis_len = vis.chars().count();
        let left_pad = (INNER_WIDTH.saturating_sub(vis_len)) / 2;

        write!(out, "{}", " ".repeat(left_pad)).ok();
        if typed_len > 0 {
            write!(out, "{}{}{}{}", ITALIC, FG_GRAY, typed, RESET).ok();
        }
        let right_pad = INNER_WIDTH.saturating_sub(left_pad + typed_len);
        write!(out, "{}", " ".repeat(right_pad)).ok();
        write!(out, "│").ok();
    }

    let mut cur_row: u16 = 8;

    // Keyboard (or blank)
    if args.nokb {
        render_blank(out, cur_row);
        cur_row += 1;
        render_blank(out, cur_row);
        cur_row += 1;
    } else {
        render_blank(out, cur_row);
        cur_row += 1;

        // Determine layout name for display
        let kb_layout = if !args.emu_out.is_empty() {
            args.emu_out.as_str()
        } else {
            "qwerty"
        };

        let rows_data = layout_rows(kb_layout);

        // Determine next char to highlight
        let next_char = if !state.complete && state.cur_ngram < state.lesson.len() {
            if state.need_space {
                None
            } else {
                state.lesson[state.cur_ngram].chars().nth(state.cur_char)
            }
        } else {
            None
        };

        let highlight = next_char.and_then(|c| find_key_pos(c, rows_data));

        if args.show_ortho {
            render_kb_ortho(out, cur_row, rows_data, highlight);
            cur_row += 7;
        } else {
            render_kb_staggered(out, cur_row, rows_data, highlight);
            cur_row += 7;
        }
    }

    // Separator before stats
    render_separator(out, cur_row);
    cur_row += 1;

    // Stats WPM line
    {
        goto(out, cur_row, 0);
        write!(out, "│").ok();
        let need_part = format!("  need >= {:3}WPM,   avg.", args.wpm);
        let avg_part = format!(" {:3}WPM", state.avg_wpm);
        let comma_part = "  ";
        let last_label = " last";
        let last_part = format!(" {:3}WPM", state.last_wpm);
        let total = need_part.len() + avg_part.len() + 2 + 4 + last_part.len();
        // Actually match original: "  need >=  40WPM,   avg.   0WPM,   last   0WPM"
        // Format: "  need >= XXX WPM,   avg.   YWPM,   last   ZWPM"
        let s = format!("  need >= {:3}WPM,   avg. {:3}WPM,   last {:3}WPM", 
            args.wpm, state.avg_wpm, state.last_wpm);
        let pad = INNER_WIDTH.saturating_sub(s.len());
        write!(out, "{}{}{}", FG_GRAY, "  need >= ", RESET).ok();
        write!(out, "{:3}", args.wpm).ok();
        write!(out, "{}WPM,   avg. {}", FG_GRAY, RESET).ok();
        write!(out, "{}{:3}WPM{}", FG_WHITE, state.avg_wpm, RESET).ok();
        write!(out, "{},   last{}", FG_GRAY, RESET).ok();
        write!(out, " {:3}WPM", state.last_wpm).ok();
        write!(out, "{}", " ".repeat(pad + s.len() - s.len())).ok();
        // Hmm this is getting complex. Let me just use a simpler format.
        write!(out, "│").ok();
    }
    cur_row += 1;

    // Stats Acc line
    {
        goto(out, cur_row, 0);
        write!(out, "│").ok();
        let s = format!("  need >= {:3}% Acc, avg. {:3}% Acc, last {:3}% Acc",
            args.acc, state.avg_acc, state.last_acc);
        let pad = INNER_WIDTH.saturating_sub(s.len());
        write!(out, "{}{}", s, " ".repeat(pad)).ok();

        // Cat overlay if --cat
        if args.cat {
            write!(out, "│").ok();
            // The cat occupies the bottom-right
            // Render cat on next few rows
        } else {
            write!(out, "│").ok();
        }
    }
    cur_row += 1;

    // Bottom border
    goto(out, cur_row, 0);
    write!(out, "╰{}╯", "─".repeat(INNER_WIDTH)).ok();

    // Cat rendering (overlaps bottom 3 rows)
    if args.cat {
        let cat_lines = ["  /\\_/\\  ", " >(•༝• )< ", " |    \\  "];
        let cat_x = (BOX_WIDTH - 13) as u16;
        let cat_base = cur_row - 2;
        for (i, &cat_line) in cat_lines.iter().enumerate() {
            goto(out, cat_base - 1 + i as u16, cat_x);
            write!(out, "{}", cat_line).ok();
        }
    }

    out.flush().ok();
}

fn render_kb_staggered(
    out: &mut impl Write,
    start_row: u16,
    rows_data: [&[&str]; 3],
    highlight: Option<(usize, usize)>,
) {
    let r0: Vec<&str> = rows_data[0].iter().copied().collect();
    let r1: Vec<&str> = rows_data[1].iter().copied().collect();
    let r2: Vec<&str> = rows_data[2].iter().copied().collect();

    let n0 = r0.len();
    let n1 = r1.len();
    let n2 = r2.len();

    let indent0 = 13usize;
    let indent1 = indent0 + 1;
    let indent2 = indent0 + 2;

    // Build border strings
    let top0 = format!("{}┌{}┐", " ".repeat(indent0), 
        (0..n0).map(|i| if i < n0-1 { "───┬" } else { "───" }).collect::<String>());
    let bot0_top1 = format!("{}└{}┘", " ".repeat(indent0),
        (0..n0).map(|i| if i < n0-1 { "┬──┴" } else { "┬──" }).collect::<String>());
    let bot1_top2 = format!("{} └{}┘", " ".repeat(indent0),
        (0..n1).map(|i| if i < n1-1 { "┬──┴" } else { "┬──" }).collect::<String>());
    let bot2 = format!("{}  └{}┘", " ".repeat(indent0),
        (0..n2).map(|i| if i < n2-1 { "───┴" } else { "───" }).collect::<String>());

    let pad_line = |s: &str| -> String {
        let len = s.chars().count();
        format!("{}{}", s, " ".repeat(INNER_WIDTH.saturating_sub(len)))
    };

    // Row 0 top border
    goto(out, start_row, 0);
    write!(out, "│{}{}{}│", FG_GRAY, pad_line(&top0), RESET).ok();

    // Row 0 keys
    goto(out, start_row + 1, 0);
    write!(out, "│{}{}│", FG_GRAY, " ".repeat(indent0)).ok();
    for (ci, key) in r0.iter().enumerate() {
        if highlight == Some((0, ci)) {
            write!(out, " {}{}{} {}│", FG_YELLOW, key, FG_GRAY, "").ok();
        } else {
            write!(out, " {} │", key).ok();
        }
    }
    let content_len = indent0 + 1 + n0 * 4;
    write!(out, "{}{}│", " ".repeat(INNER_WIDTH.saturating_sub(content_len)), RESET).ok();

    // Row 0 bottom / Row 1 top
    goto(out, start_row + 2, 0);
    write!(out, "│{}{}{}│", FG_GRAY, pad_line(&bot0_top1), RESET).ok();

    // Row 1 keys
    goto(out, start_row + 3, 0);
    write!(out, "│{}{} │", FG_GRAY, " ".repeat(indent1)).ok();
    for (ci, key) in r1.iter().enumerate() {
        if highlight == Some((1, ci)) {
            write!(out, " {}{}{} {}│", FG_YELLOW, key, FG_GRAY, "").ok();
        } else {
            write!(out, " {} │", key).ok();
        }
    }
    let content_len = indent1 + 1 + 1 + n1 * 4;
    write!(out, "{}{}│", " ".repeat(INNER_WIDTH.saturating_sub(content_len)), RESET).ok();

    // Row 1 bottom / Row 2 top
    goto(out, start_row + 4, 0);
    write!(out, "│{}{}{}│", FG_GRAY, pad_line(&bot1_top2), RESET).ok();

    // Row 2 keys
    goto(out, start_row + 5, 0);
    write!(out, "│{}{}  │", FG_GRAY, " ".repeat(indent2)).ok();
    for (ci, key) in r2.iter().enumerate() {
        if highlight == Some((2, ci)) {
            write!(out, " {}{}{} {}│", FG_YELLOW, key, FG_GRAY, "").ok();
        } else {
            write!(out, " {} │", key).ok();
        }
    }
    let content_len = indent2 + 2 + 1 + n2 * 4;
    write!(out, "{}{}│", " ".repeat(INNER_WIDTH.saturating_sub(content_len)), RESET).ok();

    // Row 2 bottom
    goto(out, start_row + 6, 0);
    write!(out, "│{}{}{}│", FG_GRAY, pad_line(&bot2), RESET).ok();
}

fn render_kb_ortho(
    out: &mut impl Write,
    start_row: u16,
    rows_data: [&[&str]; 3],
    highlight: Option<(usize, usize)>,
) {
    let indent = 13usize;
    let n = 12usize;

    // Pad rows to 12 with empty strings
    let pad_row = |row: &[&str]| -> Vec<&str> {
        let mut v: Vec<&str> = row.to_vec();
        while v.len() < n { v.push(""); }
        v
    };

    let r0 = pad_row(rows_data[0]);
    let r1 = pad_row(rows_data[1]);
    let r2 = pad_row(rows_data[2]);

    let build_top = || format!("{}┌{}┐", " ".repeat(indent),
        (0..n).map(|i| if i < n-1 { "───┬" } else { "───" }).collect::<String>());
    let build_mid = || format!("{}├{}┤", " ".repeat(indent),
        (0..n).map(|i| if i < n-1 { "───┼" } else { "───" }).collect::<String>());
    let build_bot = || format!("{}└{}┘", " ".repeat(indent),
        (0..n).map(|i| if i < n-1 { "───┴" } else { "───" }).collect::<String>());

    let pad_line = |s: &str| -> String {
        let len = s.chars().count();
        format!("{}{}", s, " ".repeat(INNER_WIDTH.saturating_sub(len)))
    };

    let render_row = |out: &mut dyn Write, row: &[&str], row_idx: usize| {
        write!(out, "│{}{}│", FG_GRAY, " ".repeat(indent)).ok();
        for (ci, &key) in row.iter().enumerate() {
            let display = if key.is_empty() { "△" } else { key };
            if !key.is_empty() && highlight == Some((row_idx, ci)) {
                write!(out, " {}{}{} │", FG_YELLOW, display, FG_GRAY).ok();
            } else {
                write!(out, " {} │", display).ok();
            }
        }
        let content_len = indent + 1 + n * 4;
        write!(out, "{}{}│", " ".repeat(INNER_WIDTH.saturating_sub(content_len)), RESET).ok();
    };

    goto(out, start_row, 0);
    write!(out, "│{}{}{}│", FG_GRAY, pad_line(&build_top()), RESET).ok();

    goto(out, start_row + 1, 0);
    render_row(out, &r0, 0);

    goto(out, start_row + 2, 0);
    write!(out, "│{}{}{}│", FG_GRAY, pad_line(&build_mid()), RESET).ok();

    goto(out, start_row + 3, 0);
    render_row(out, &r1, 1);

    goto(out, start_row + 4, 0);
    write!(out, "│{}{}{}│", FG_GRAY, pad_line(&build_mid()), RESET).ok();

    goto(out, start_row + 5, 0);
    render_row(out, &r2, 2);

    goto(out, start_row + 6, 0);
    write!(out, "│{}{}{}│", FG_GRAY, pad_line(&build_bot()), RESET).ok();
}

// ─────────────────────────────────────────
// Main
// ─────────────────────────────────────────
fn main() {
    let args = match Args::parse() {
        Ok(a) => a,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };

    let ngram_list = get_ngram_list(&args);
    let lesson = generate_lesson(&ngram_list, args.combi, args.rep);
    let mut state = AppState::new(lesson);

    let mut raw = match term::RawTerminal::new() {
        Ok(r) => r,
        Err(e) => {
            eprintln!("Failed to initialize terminal: {}", e);
            std::process::exit(1);
        }
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    render(&mut out, &state, &args);

    let mut running = true;

    while running {
        match raw.read_char() {
            Some('\x1b') => {
                // Check for escape sequence or just ESC
                raw.set_timeout(50); // ms
                match raw.read_char() {
                    Some('[') => {
                        // Arrow key or function key - consume and ignore
                        raw.read_char(); // consume sequence
                    }
                    Some(_) => {}
                    None => {
                        // Just ESC key
                        running = false;
                    }
                }
                raw.reset_timeout();
            }
            Some('\x03') => {
                // Ctrl+C
                running = false;
            }
            Some('\x7f') | Some('\x08') => {
                // Backspace - ignore
            }
            Some(c) if c.is_alphanumeric() || c.is_ascii_punctuation() || c == ' ' => {
                let mapped = map_char_emulation(c, &args.emu_in, &args.emu_out);

                if state.complete {
                    // Any key advances to next lesson
                    let lesson_passed = state.last_wpm >= args.wpm && state.last_acc >= args.acc;
                    if lesson_passed {
                        state.passed += 1;
                    } else {
                        state.failed += 1;
                    }
                    state.lesson_num += 1;
                    let new_lesson = generate_lesson(&ngram_list, args.combi, args.rep);
                    state.reset_lesson(new_lesson);
                    // Feed this char to the new lesson
                    state.handle_char(mapped);
                } else {
                    state.handle_char(mapped);
                }

                render(&mut out, &state, &args);
            }
            Some(_) => {}
            None => {}
        }
    }

    drop(raw);
    write!(out, "\x1b[?25h").ok();  // show cursor
    write!(out, "\x1b[2J\x1b[H").ok();  // clear
    out.flush().ok();
}
