        // Clear flags that affect raw mode
        t.c_iflag &= !(
            (1 << 0)  |  // IGNBRK
            (1 << 1)  |  // BRKINT
            (1 << 3)  |  // IGNPAR
            (1 << 4)  |  // PARMRK
            (1 << 5)  |  // INPCK
            (1 << 6)  |  // ISTRIP
            (1 << 8)  |  // INLCR
            (1 << 9)  |  // IGNCR
            (1 << 10) |  // ICRNL
            (1 << 11) |  // IUCLC
            (1 << 14) |  // IXON
            (1 << 15)    // IXANY
        );
        t.c_oflag &= !(1 << 0);  // ~OPOST
        t.c_cflag &= !((3 << 4) | (1 << 6) | (3 << 20)); // ~CSIZE, ~CSTOPB, ~PARENB
        t.c_cflag |= 3 << 4; // CS8
        t.c_cflag |= 1 << 7; // CREAD
        t.c_lflag &= !(
            (1 << 3)  |  // ECHO
            (1 << 4)  |  // ECHOE  
            (1 << 5)  |  // ECHOK
            (1 << 7)  |  // ECHONL
            (1 << 8)  |  // ICANON
            (1 << 9)  |  // IEXTEN
            (1 << 14)    // ISIG
        );
