        sys::make_raw(&mut raw);

        if !sys::set_termios(fd, &raw) {
            return Err(io::Error::new(io::ErrorKind::Other, "tcsetattr raw failed"));
        }

        Ok(RawTerminal { fd, orig, raw })
    }

