        let deciseconds = ((ms + 99) / 100) as u8;
        let deciseconds = deciseconds.max(1);
        let mut t = self.raw.clone();
        sys::make_timeout(&mut t, deciseconds);
        sys::set_termios(self.fd, &t);
    }

    pub fn reset_timeout(&mut self) {
        sys::set_termios(self.fd, &self.raw);
    }

    pub fn read_char(&mut self) -> Option<char> {
        let mut buf = [0u8; 1];
        let n = unsafe {
            libc_read(self.fd, buf.as_mut_ptr(), 1)
