            // 2-byte
            let mut buf2 = [0u8; 1];
            unsafe { libc_read(self.fd, buf2.as_mut_ptr(), 1); }
            char::from_u32(((b & 0x1F) as u32) << 6 | (buf2[0] & 0x3F) as u32)
        } else if b & 0xF0 == 0xE0 {
            // 3-byte
            let mut buf2 = [0u8; 2];
            unsafe { libc_read(self.fd, buf2.as_mut_ptr(), 2); }
            char::from_u32(
                ((b & 0x0F) as u32) << 12 |
                ((buf2[0] & 0x3F) as u32) << 6 |
                (buf2[1] & 0x3F) as u32
            )
        } else if b & 0xF8 == 0xF0 {
            // 4-byte
            let mut buf2 = [0u8; 3];
            unsafe { libc_read(self.fd, buf2.as_mut_ptr(), 3); }
            char::from_u32(
                ((b & 0x07) as u32) << 18 |
                ((buf2[0] & 0x3F) as u32) << 12 |
                ((buf2[1] & 0x3F) as u32) << 6 |
                (buf2[2] & 0x3F) as u32
            )
        } else {
            None
        }
    }
}

extern "C" {
    fn read(fd: i32, buf: *mut u8, count: usize) -> isize;
}

unsafe fn libc_read(fd: i32, buf: *mut u8, count: usize) -> isize {
    read(fd, buf, count)
}

impl Drop for RawTerminal {
    fn drop(&mut self) {
        sys::set_termios(self.fd, &self.orig);
    }
}

pub fn get_terminal_size() -> Option<(u16, u16)> {
    let fd = io::stdout().as_raw_fd();
    sys::get_winsize(fd)
}
