        // Linux-specific cfmakeraw equivalent
        // Clear flags that affect raw mode
        t.c_iflag &= !(
            (1 << 0)  |  // IGNBRK
            (1 << 1)  |  // BRKINT
            (1 << 3)  |  // IGNPAR
            (1 << 4)  |  // PARMRK
            (1 << 5)  |  // INPCK
