use std::io::Write;
use std::os::unix::io::AsRawFd;

extern "C" {
    fn tcgetattr(fd: i32, t: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, action: i32, t: *const Termios) -> i32;
    fn read(fd: i32, buf: *mut u8, n: usize) -> isize;
}

#[repr(C)]
#[derive(Clone)]
struct Termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

fn main() {
    let fd = std::io::stdin().as_raw_fd();

    let mut orig = Termios {
        c_iflag: 0, c_oflag: 0, c_cflag: 0, c_lflag: 0,
        c_line: 0, c_cc: [0; 32], c_ispeed: 0, c_ospeed: 0,
    };

    unsafe {
        if tcgetattr(fd, &mut orig) != 0 {
            eprintln!("tcgetattr failed");
            return;
        }
    }

    let mut raw = orig.clone();
    // Make raw
    raw.c_iflag &= !(
        (1 << 0) | (1 << 1) | (1 << 3) | (1 << 4) | (1 << 5) | (1 << 6) | 
        (1 << 8) | (1 << 9) | (1 << 10) | (1 << 11) | (1 << 14) | (1 << 15)
    );
    raw.c_oflag &= !(1 << 0);
    raw.c_cflag &= !((3 << 4) | (1 << 6) | (3 << 20));
    raw.c_cflag |= 3 << 4;
    raw.c_cflag |= 1 << 7;
    raw.c_lflag &= !(
        (1 << 3) | (1 << 4) | (1 << 5) | (1 << 7) | (1 << 8) | (1 << 9) | (1 << 14)
    );
    raw.c_cc[6] = 1;  // VMIN
    raw.c_cc[5] = 0;  // VTIME

    unsafe {
        if tcsetattr(fd, 0, &raw) != 0 {
            eprintln!("tcsetattr failed");
            return;
        }
    }

    let stdout = std::io::stdout();
    let mut out = stdout.lock();

    write!(out, "Ready (press keys, ESC to quit):\r\n").ok();
    out.flush().ok();

    loop {
        let mut b = [0u8; 1];
        let n = unsafe { read(fd, b.as_mut_ptr(), 1) };
        if n <= 0 { break; }
        write!(out, "Got: {:02x} ({})\r\n", b[0], b[0] as char).ok();
        out.flush().ok();
        if b[0] == 27 { break; }  // ESC
    }

    // Restore
    unsafe { tcsetattr(fd, 0, &orig); }
    writeln!(out, "\r\nDone").ok();
}
