# Looking at the original pattern:
# GREEN "✔: 0, " RED "✘: 0    " RESET "│"
# Check = "✔: 0", x = "✘: 0", with 4 trailing spaces in the x part

new_header_write = '''        write!(out, "{}", left).ok();
        write!(out, "{}", " ".repeat(spaces)).ok();
        // Original: green spans include ", ", red spans include trailing spaces
        write!(out, "{}{}, {}", FG_GREEN, check, RESET).ok();
        write!(out, "{}{}    {}│", FG_RED, x, RESET).ok();
        // Note: │ is written at end of red span (already included above)
        return;'''

# Actually wait - the │ is the right border of the box!
# Let me check the actual header write sequence:
# The header writes:
# │ + left_text + spaces + GREEN("✔: 0, ") + RED("✘: 0    ") + RESET + │
# vs mine: │ + left_text + spaces + GREEN("✔: 0") + RESET + ", " + RED("✘: 0") + RESET + "    │"
