import subprocess, re

# Let me look at the original stats escape codes more carefully
orig_esc = subprocess.run(['tmux', 'capture-pane', '-t', 'orig', '-p', '-e'],
                           capture_output=True).stdout.decode('utf-8', errors='replace')
orig_lines = orig_esc.split('\n')

# Stats lines
for i in [16, 17]:
    line = orig_lines[i]
    # Split into colored segments
    def show_colored_parts(s, max_parts=20):
        parts = re.split(r'(\x1b\[[\d;]*m)', s)
        result = []
        for part in parts:
            if part.startswith('\x1b['):
                result.append(f"[{part[2:-1]}]")
            else:
                if part.strip() or part:
                    result.append(repr(part[:20]))
        return ' '.join(result[:max_parts*2])

    print(f"\nStats line {i}:")
    print(show_colored_parts(line))
